        private void Frm_Json_Load(object sender, EventArgs e)
        {
            if (DateTime.Now.DayOfWeek == DayOfWeek.Monday)
            {
                Dtp_Fecha.Value = DateTime.Now.AddDays(-3);
            }
            else
            {
                Dtp_Fecha.Value = DateTime.Now.AddDays(-2);
            }
            //////////////////////////////////////////////////////
            ///
            try
            {
                IList<spSelectBitacoraSecuencialesAmexJSON_Result> Bitacora = new List<spSelectBitacoraSecuencialesAmexJSON_Result>();
                using (CYBEREntities DB = new CYBEREntities())
                {
                    Bitacora = DB.spSelectBitacoraSecuencialesAmexJSON().ToList();
                }
            
                DataTable Result = new DataTable();
                Result.Columns.Add("TIPO");
                Result.Columns.Add("SECUENCIAL");
                Result.Columns.Add("FECHA DE PROCESO");
                Result.Columns.Add("USUARIO");
                Result.Columns.Add("TOTAL");
                Result.Columns.Add("INICIO");
                Result.Columns.Add("FINAL");
                if (Bitacora.Count > 0)
                {            
                    for (int i = 0; i < Bitacora.Count; i++)
                    {
                        object[] objeto = new object[7];
                        objeto[0] = Bitacora[i].tipoJSON;
                        objeto[1] = Bitacora[i].secuencialJSON;
                        objeto[2] = Bitacora[i].FechaProceso;
                        objeto[3] = Bitacora[i].userCreador;
                        objeto[4] = Bitacora[i].totalRegistros;
                        DateTime strdate = Convert.ToDateTime(Bitacora[i].horaInicio);
                        string horaInicioStr = strdate.ToString("hh:mm:ss tt");
                        objeto[5] = horaInicioStr;
                        DateTime strdate2 = Convert.ToDateTime(Bitacora[i].horaFinal);
                        string horaFinStr = strdate2.ToString("hh:mm:ss tt");
                        objeto[6] = horaFinStr;
                        Result.Rows.Add(objeto);
                    }
                    Dgv_Informacion.DataSource = Result;
                }
                if (!(loginGlobal.ToUpper() == "ABTDN" || loginGlobal.ToUpper() == "AANAY" || loginGlobal.ToUpper() == "AAHTQ" || loginGlobal.ToUpper() == "ABPGN" || loginGlobal.ToUpper() == "ABYYL"))
                {
                    checkBox1.Visible = false;
                }
            }
            catch (Exception tmp)
            {
                var msg = tmp.Message;
            }
            //////////////////////////////////////////////////////
        }
        private async void Btn_MT_Click(object sender, EventArgs e)
        {
            OpenFileDialog archivo = new OpenFileDialog();
            //archivo.Filter = "Archivos JSON (*.json)|*.json"; //le indicamos el tipo de filtro en este caso que busque solo los archivos excel
            archivo.FileName = string.Empty;//inicializamos con vacio el nombre del archivo
            archivo.Multiselect = true;
            if (archivo.ShowDialog() == System.Windows.Forms.DialogResult.OK)
            {
                int totalArchivos = archivo.FileNames.Count();
                bool permitir = true;
                string tipoArch = "";
                if (totalArchivos > 1)
                {
                    while (true)
                    {
                        var result = MessageBox.Show("HAY MÁS DE 1 JSON SELECCIONADO, ¿ESTO ES CORRECTO?", "MÁS DE 1 JSON", MessageBoxButtons.YesNo);
                        if (result == DialogResult.No)
                        {
                            permitir = false;
                            break;
                        }
                        for (int i = 0; i < totalArchivos; i++)
                        {
                            tipoArch = archivo.FileNames[i];
                            if (!tipoArch.Contains("ACTIONHISTOB"))
                            {
                                MessageBox.Show("Hay un JSON que no es ACTIONHIST", "ERROR", MessageBoxButtons.OK);
                                permitir = false;
                                break;
                            }
                        }
                        break;
                    }
                }
                if (permitir)
                {
                    string Desk = Environment.GetFolderPath(Environment.SpecialFolder.Desktop); //Se obtiene la ruta del Escritorio-Desktop y se almacena como string en Desk
                    string ruta = Desk + "\\JSON\\PROCESADOS\\" + DateTime.Now.ToString("dd-MM-yyyy"); //Se crea un string que será la concatenación            
                    string nombreArchivo = "Procesado - " + DateTime.Now.ToString("hh.mm.ss") + ".txt";
                    if (!Directory.Exists(ruta)) //Si el directorio no existe lo crea.
                    {
                        Directory.CreateDirectory(ruta);
                    }
                    File.WriteAllText(ruta + "\\" + nombreArchivo, ""); //Se inicializa el archivo y se le escribe un vacio solamente para crear el documento.
                    StringBuilder SB_ = new StringBuilder();
                    for (int i = 0; i < totalArchivos; i++)
                    {
                        string nombreJSON = "";
                        Txt_Archivo.Text = archivo.FileNames[i];
                        pictureBox1.Visible = true;
                        await EjecutarAsynJsonTotal();
                        Dgv_Informacion.Show();
                        pictureBox1.Visible = false;
                        nombreJSON = archivo.FileNames[i];
                        SB_.AppendLine(nombreJSON);
                        File.WriteAllText(ruta + "\\" + nombreArchivo, SB_.ToString()); //Se inicializa el archivo y se le escribe un vacio solamente para crear el documento.
                    }
                }
                Lbl_Total.Visible = true;
                Lbl_Total.Text = "Total : " + (Dgv_Informacion.Rows.Count - 1);
            }
        }
