        /// <summary>
        /// Obtiene la AgencyAssignmentDate  (Fecha de asignación) que se tiene en la Tabla  de Oracle..
        /// </summary>
        public DateTime obtenerAssignmentDate(string accountRecibida) //Comienza Ejecución 
        {
            string accountNumber = accountRecibida;
            string Servidor = "192.168.90.10:1521/sertecp"; //Se almacenan las credenciales para hacer login en la base de Oracle.
            string Usuario = "SACASIG";
            string Password = "4S1gn4c10n3s*2026";
            IList<DateTime?> FechaU = new List<DateTime?>(); //Se crea una lista de fechas llamada FechaU
            string queryString;
            queryString = @"SELECT camposaseleccionar FROM rcvry.tabladelacualseobtiene WHERE accountnumber = " + accountNumber + "order by 1";
            using (OracleConnection con = new OracleConnection(string.Format("Data Source={0};User Id={1};Password={2}; Connection Timeout=6000", Servidor, Usuario, Password)))
            // Usando las credenciales que se crearon anteriormente, se realiza la conexión a la base de Datos de Oracle.
            {
                using (OracleCommand command = new OracleCommand(queryString, con)) //Se crea un Comando de Oracle con nuestra Query "queryString" a través de la conexión con la base de datos.
                //Nuestra query "queryString" es la que se declaró anteriormente, @"SELECT CUENTA,FECHA,D1,D2,D3,....etc... de la tabla RPT_UPDATE_1.
                {
                    OracleDataAdapter da = new OracleDataAdapter(); //Nuevamente se crea un Adaptador de Oracle
                    da.SelectCommand = command; //Utilizando el adaptador, se ejecuta command, que es el queryString y la conexión anterior.
                    DsRetorno = new DataTable(); //Se crea un DataTable llamado DsRetorno.
                    da.Fill(DsRetorno); //Utilizando el comando command, que vive en el adaptador. El resultado del query se almacena en la DataTable DsRetorno.
                }
            }
            DateTime fechaAsignacion;
            fechaAsignacion = Convert.ToDateTime(DsRetorno.Rows[0][0]);
            return fechaAsignacion;
        }

        /// <summary>
        ///  Modifica un número para que siempre contenga 2 decimales despues del punto decimal.
        ///  El número esperado debe ser tipo string.
        ///  Y el valor devuelto es el mismo numero en tipo string, sin punto decimal y con 2 decimales.
        /// </summary>
        /// <param name="myNumber"></param>
        /// <returns name = "myNumber"></returns>
        public static string DoFormat(string myNumber)
        {
            if (myNumber.Contains("."))
            {
                string[] x = myNumber.ToString().Split('.');
                if (x[1].Length == 2)
                {
                    return myNumber;
                }
                else
                {
                    myNumber = myNumber + "0";
                }
            }
            else
            {
                myNumber = myNumber + "00";
            }
            return myNumber;
        }

        /// <summary>
        /// Genera Clave HASH de un JSON. Para su posterior arribo a la plataforma de AMEX.
        /// Recibe un Arreglo de string llamado Dividido, y un string llamado RutaCompleta.
        /// </summary>
        /// <param name="Dividido" type></param>
        /// <param name="RutaCompleta"></param>
        public void GenerarHash(string[] Dividido, string RutaCompleta)
        {
            string ReportID = "".PadRight(15);
            string Number = "".PadRight(8);
            string Hash = "".PadRight(64);
            Number = Dividido[6].Substring(0, 4).PadLeft(8, '0');
            string contents = File.ReadAllText(RutaCompleta);
            //string a2 = SHA256_.sha256(contents);
            string a3 = SHA256_.sha256_(contents);
            //string a4 = SHA256_.getHashSha256(contents);
            //string a5 = SHA256_.GetSha256FromString(contents);
            //string a6 = SHA256_.Sha256encrypt(contents);
            string archivo = "";
            string archivoC = "";
            string NombreJson = Path.GetFileName(RutaCompleta);
            string Ruta = Environment.GetFolderPath(Environment.SpecialFolder.Desktop);
            NombreJson = Dividido[0] + "." + Dividido[2] + "." + "UNITECH" + "." + Dividido[3] + "." + Dividido[4] + "." + Dividido[5] + "." + Dividido[6];
            switch (Dividido[3].ToString())
            {
                case "MIGRAT":
                    ReportID = "ACORNSTPLCMNT".PadRight(15);
                    archivo = Ruta + "\\JSON\\MIGRAT\\" + DateTime.Now.ToString("dd-MM-yyyy");
                    if (!Directory.Exists(archivo))
                    {
                        Directory.CreateDirectory(archivo);
                    }
                    archivoC = "C:";
                    if (!Directory.Exists(archivoC))
                    {
                        Directory.CreateDirectory(archivoC);
                    }
                    break;
                case "PLCMNT":
                    ReportID = "ACORNSTPLCMNT".PadRight(15);
                    archivo = Ruta + "\\JSON\\PLACEMENT\\" + DateTime.Now.ToString("dd-MM-yyyy");
                    if (!Directory.Exists(archivo))
                    {
                        Directory.CreateDirectory(archivo);
                    }
                    archivoC = "C:";
                    if (!Directory.Exists(archivoC))
                    {
                        Directory.CreateDirectory(archivoC);
                    }
                    break;
                case "RECALL":
                    ReportID = "ACORNSTRECALL".PadRight(15);
