        }

        /// <summary>
        /// Genera el HASH de un JSON sin tener que procesar el JSON o sin tener que generarlo. Sirve para obtener solo el archivo UNITECH.
        /// </summary>
        /// <param name="rutaCompleta"></param>
        public void GenerarHash(string rutaCompleta)
        {
            DateTime horaInicio = DateTime.Now;
            string NombreJson = Path.GetFileName(rutaCompleta); //Almacena solamente el nombre del archivo.
            string desktop = Environment.GetFolderPath(Environment.SpecialFolder.Desktop);
            string[] Dividido = NombreJson.Split('.');
            string contents;
            if (Dividido.Length == 7 && Dividido[2] == "ACORN")
            {
                string ReportID = "".PadRight(15);
                string Number = "".PadRight(8);
                string Hash = "".PadRight(64);
                Number = Dividido[6].Substring(0, 4).PadLeft(8, '0');
                contents = File.ReadAllText(rutaCompleta);
                string a3 = SHA256_.sha256_(contents);
                string archivo = "";
                NombreJson = Dividido[0] + "." + Dividido[1] + "." + "UNITECH" + "." + Dividido[3] + "." + Dividido[4] + "." + Dividido[5] + "." + Dividido[6];
                string guardarHASH = desktop + "\\HASH";
                switch (Dividido[3].ToString())
                {
                    case "PLCMNT":
                        ReportID = "ACORNSTPLCMNT".PadRight(15);
                        archivo = guardarHASH + "\\PLACEMENT\\" + DateTime.Now.ToString("dd-MM-yyyy");
                        if (!Directory.Exists(archivo))
                        {
                            Directory.CreateDirectory(archivo);
                        }
                        break;
                    case "RECALL":
                        ReportID = "ACORNSTRECALL".PadRight(15);
                        archivo = guardarHASH + "\\RECALL\\" + DateTime.Now.ToString("dd-MM-yyyy");
                        if (!Directory.Exists(archivo))
                        {
                            Directory.CreateDirectory(archivo);
                        }
                        break;
                    case "UPDATESOB":
                        ReportID = "ACORNSTUPDOB".PadRight(15);
                        archivo = guardarHASH + "\\UPDATESOB\\" + DateTime.Now.ToString("dd-MM-yyyy");
                        if (!Directory.Exists(archivo))
                        {
                            Directory.CreateDirectory(archivo);
                        }
                        break;
                    case "ACTIONHISTOB":
                        ReportID = "ACORNSTHISTOB".PadRight(15);
                        archivo = guardarHASH + "\\ACTION\\" + DateTime.Now.ToString("dd-MM-yyyy");
                        if (!Directory.Exists(archivo))
                        {
                            Directory.CreateDirectory(archivo);
                        }
                        break;
                    case "UPDATESIB":
                        ReportID = "ACORNSTUPDIB".PadRight(15);
                        archivo = guardarHASH + "\\UPDATESIB\\" + DateTime.Now.ToString("dd-MM-yyyy");
                        if (!Directory.Exists(archivo))
                        {
                            Directory.CreateDirectory(archivo);
                        }
                        break;
                }
                string totalText = ReportID + Number + a3;
                string nueva = archivo + "\\" + Path.GetFileName(rutaCompleta);
                System.IO.File.Copy(rutaCompleta, nueva, true);
                File.WriteAllText(archivo + "\\" + NombreJson, totalText);
                using (CYBEREntities DB = new CYBEREntities())
                {
                    DB.spInsertSecuencialAmexJSON(NombreJson, Number.Substring(Number.Length - 4), "HASH " + Dividido[3].ToString(), loginGlobal, null, horaInicio, DateTime.Now);
                    DB.spInsertHASHIB(NombreJson, Dividido[6], totalText, 1);
                }
                MessageBox.Show("Cifrado HASH generado", "LISTO", MessageBoxButtons.OK);
            }
            else
            {
                if (Dividido.Length == 8 && Dividido[7] == "RECEIVED")
                {
                    string nombreBus = Dividido[0] + "." + Dividido[2] + "." + Dividido[1] + "." + Dividido[3] + "." + Dividido[4] + "." + Dividido[5] + "." + Dividido[6];
                    contents = File.ReadAllText(rutaCompleta);
                    List<int?> resultado = new List<int?>();
                    using (CYBEREntities DB = new CYBEREntities())
                    {
                        resultado = DB.spInsertHASHIB(nombreBus, Dividido[6].ToString(), contents, 2).ToList();
                    }
                    if (resultado.Count != 0)
                    {
                        switch (resultado[0])
                        {
                            case 1:
                                MessageBox.Show("Ya existia un registro con el mismo nombre, secuencial y sus hashes coinciden", "HASH SI COINCIDE", MessageBoxButtons.OK);
                                break;
                            case 2:
                                MessageBox.Show("Ya existia un registro con el mismo nombre, secuencial pero sus hashes NO coinciden", "HASH NO COINCIDE", MessageBoxButtons.OK);
                                break;
                            case 3:
                                MessageBox.Show("NO existe un registro con el mismo nombre, secuencial, concluyendo operación", "No existen registros", MessageBoxButtons.OK);
                                break;
                            default:
                                break;
                        }
                    }
                    else
                    {
                        MessageBox.Show("Algo falló", "REVISAR", MessageBoxButtons.OK);
                    }
                }
                else
                    MessageBox.Show("Estructura de Nombre erronea, revisar", "REVISAR", MessageBoxButtons.OK);
            }
        }

        /// <summary>
        /// Genera Archivo mt para realizar recall.
        /// </summary>
        /// <param name="RutaCompleta"></param>
        /// <param name="archivo"></param>
        /// <param name="resultsRecall"></param>
        public void GenerarRecall(string RutaCompleta, string archivo, Ent_Json_Recall.RootObject resultsRecall, int seqNo) //Método invocado en la carga de un archivo tipo RECALL. 
        {
            ArchivoRecall archivoRecall; //Se crea un objeto de la clase ArchivoRecall.
            string archivoSB_ = Path.GetDirectoryName(RutaCompleta); //Se obtiene la ruta del archivo JSON que se cargó.
            string ruta_ = archivo + "\\JSONRC" + seqNo + "-" + DateTime.Now.ToString("dd-MM-yyyy HHmmss") + ".mt";//Y se generá la nueva ruta donde se dejará el archivo .mt que se creará al procesar el JSON.
            File.WriteAllText(ruta_, ""); //Se inicializa el archivo y se le escribe un vacio solametne para crear el documento.
            if (resultsRecall != null) //Si el árbol del JSON Recall se encuentra con algun nodo, es decir no vacío.
            {
                if (resultsRecall.accountRecallInfoList != null) //Y si la entidad accountRecallInfoList contiene información.
                {
                    for (int i = 0; i < resultsRecall.accountRecallInfoList.Count; i++) //Se recorrerá toda la entidad accountRecallInfoList para obtener la información de todos los registros.
                    {
                        StringBuilder SB_ = new StringBuilder(); //Se inicializa un objeto de la clase StringBuilder, para poder concatenar el texto que se utilizará.
                        archivoRecall = new ArchivoRecall(); //se instancia el objeto archivoRecall con las propiedades de la clase ArchivoRecall.
                        archivoRecall = ValidacionArchivoRecall(i, resultsRecall.accountRecallInfoList[i]); //Se manda llamar la función ValidacionArchivoRecall que recibirá el int del contador del for que recorre accountRecallInfoList y la entidad accountRecallInfoList en el indice i.
                        //además recibirá la entidad accountRecallInfoList en el indice del contador. 
                        string cade = Cadena(9, null, null, null, null, null, null, null, null, null, archivoRecall); //Una vez que el objeto archivoRecall ha sido modificado en sus propiedades con base a lo obtenido en la entidad JSON.
                        //Se manda llamar la función Cadena, enviando un numero 9 para entrar en el caso de los recall. Lo que hará que se concatene lo siguiente:
                        //archivoRecall.DATE + archivoRecall.TIME + archivoRecall.ACCOUNTNUMBER + archivoRecall.TRANSACTION_CODE + archivoRecall.FIELD_CODE + archivoRecall.FILL + archivoRecall.FLAG + archivoRecall.RECOVERER_CODE + archivoRecall.RECOVERER_ID + archivoRecall.LOAN_CODE + archivoRecall.FILLER;
                        SB_.AppendLine(cade);//Finalmente se añade todo al stringbuilder SB_.
                        File.AppendAllText(ruta_, SB_.ToString());//Y se añade toda la linea al texto del archivo que existe mt que existe en ruta.
                        using (CYBEREntities DB = new CYBEREntities())
                        {
                            //Se almacena un registro en la Bitacora sobre la creación de un archivo recall.
                            DB.spInsertAmexBitacora(resultsRecall.accountRecallInfoList[i].accountNumber, "", "RECALL", DateTime.Now, resultsRecall.header.balancingSeqNo.ToString().PadLeft(4, '0') + " RECALL", 1);
                        }
                    }
                }
            }
        }

        /// <summary>
        /// Convierte a una cadena de texto y después la escribe en un archivo de texto, todo lo encontrado en 
        /// cada fila de un DataTable. Se utiliza para la generación del archivo de asignación del ACTIONHIST
        /// </summary>
        /// <param name="DB"></param>
        /// <param name="Ruta"></param>
        public void GenerarArchivotxt(DataTable DB, string Ruta) //Método llamado al generar un archivo de asignación para un ACTIONHIST.
        {
            int i = 0;//Se inicializa un entero i en 0s.
            StreamWriter sw = null;//Y se crea un objeto de la clase StreamWriter para poder escribir en el archivo.
            sw = new StreamWriter(Ruta, false);//se le indica la ruta donde se modificará el archivo.
            foreach (DataRow row in DB.Rows)//Después, por cada DataRow en el DataTable DB.
            {
                object[] array = row.ItemArray;//Se tomará la fila completa, y se introducirá a un arreglo de objetos.
                for (i = 0; i < array.Length - 1; i++)//Y para cada indice elemento de ese arreglo (cada columna del datatable); se realizará que...
                {
                    sw.Write(array[i].ToString());//Se convertirá en cadena lo encontrado en cada elemento del array y se escribirá en una linea del archivo.
                }
                sw.Write(array[i].ToString());//Se escribe lo último
                sw.WriteLine();//Y se plasma la útima linea en el archivo.
            }
            sw.Close();//Se cierra la conexión del streamWriter
            DB.Clear();//Y se elimina de memoria lo que exista en el DataTable
            DB = null;//finalmente se le asigna u valor nudo al DataTable.
        }

