        /// <summary>
        /// Almacena en la BD en la Tabla Tab_Amex_Productos, el producto nuevo
        /// almacenando la Cuenta, el tipo, la fecha, la fecha de ingreso, y el segmento del nuevo producto.
        /// </summary>
        /// <param name="Cuenta"></param>
        /// <param name="Tipo"></param>
        /// <param name="Fecha"></param>
        /// <param name="Segmento"></param>
        public void Guardar_Producto(string Cuenta, string Tipo, string Fecha, string Segmento)
        {
            Tab_Amex_Productos Productos_ = new Tab_Amex_Productos();
            Productos_.TBAXPSCUENTA = Cuenta;
            Productos_.TBAXPSTIPO = Tipo;
            Productos_.TBAXPSFECHA = Fecha;
            Productos_.TBAXPSINGRESO = DateTime.Now;
            Productos_.TBAXPSSEGMENTO = Segmento;
            using (CYBEREntities DB = new CYBEREntities())
            {
                DB.Tab_Amex_Productos.Add(Productos_);
                DB.SaveChanges();
            }
        }

