                    if (resultsPlacement.caseInfoList[i].accountInfoList[0].demographics != null) //If demographics. INICIO
                    {
                        // LASTNAME // RUTA: resultsPlacement->caseInfoList[i]->accountInfoList[0]->demographics->lastName
                        if (resultsPlacement.caseInfoList[i].accountInfoList[0].demographics.lastName != null) //If LastName. INICIO
                        {
                            //Version R9.8.1 Se realiza cambio, añadiendo expresión regular para eliminar caracteres raros por espacios en blanco. Ricardo Cervantes 23-03-2020
                            string token = resultsPlacement.caseInfoList[i].accountInfoList[0].demographics.lastName.ToString();
                            accountMaster.LastName = Regex.Replace(token, @"[^a-zA-z0-9 =]+", " ").PadRight(25).Substring(0, 25); //DEBE SER LONGITUD 25. Se añade "=" a petición de Miriam Trujano.
