                        if (resultsPlacement.caseInfoList[i].accountInfoList[0].demographics.phones != null) //If Phones[]. INICIO
                        {
                            //HOMEPHONE Y WORKPHONE // RUTA: resultsPlacement->caseInfoList[i]->accountInfoList[0]->demographics->phones[]->number
                            int tamphones = resultsPlacement.caseInfoList[i].accountInfoList[0].demographics.phones.Count();
                            string[] phoneH;
                            string[] phoneW;
                            char[] charToTrim = { ' ' }; //Se definen los caracteres a eliminar. En este caso son espacios.
                            for (int n = 0; n < tamphones; n++)//Ciclo FOR, para revisar toda la lista phones[] En busca de un HomePhone.
                            {
                                if (resultsPlacement.caseInfoList[i].accountInfoList[0].demographics.phones[n].number != null)//If HomePhone INICIO.
                                {
                                    if (resultsPlacement.caseInfoList[i].accountInfoList[0].demographics.phones[n].typeCode != null)
                                    {
                                        if (resultsPlacement.caseInfoList[i].accountInfoList[0].demographics.phones[n].typeCode.ToString() == "H-HOME" || resultsPlacement.caseInfoList[i].accountInfoList[0].demographics.phones[n].typeCode.ToString() == "H_HOME") //Si posee el codigo H-Home es un HomePhone.
                                        {
                                            string HomePhoneTRIM = resultsPlacement.caseInfoList[i].accountInfoList[0].demographics.phones[n].number.ToString();//Almacenamos, lo que haya en number. En una string result.
                                            string result = HomePhoneTRIM.Trim(charToTrim); //Se realiza el TRIM a result.Eliminando espacios al inicio y al final.
                                            phoneH = result.Split(' ');
                                            result = "";
                                            for (int h = 0; h < phoneH.Length; h++)
                                            {
                                                if (phoneH[h] != "")
                                                {
                                                    result = result + phoneH[h].ToString() + " ";
                                                }
                                            }
                                            if (result.Length < 16)//Se verifica que la longitud sea menos 16 para añadir espacios en blanco. Y no desfasar ningun campo.
                                            {
