                                        {
                                            string WorkPhoneTRIM = resultsPlacement.caseInfoList[i].accountInfoList[0].demographics.phones[nn].number.ToString();//Almacenamos, lo que haya en number. En una string result.
                                            string result = WorkPhoneTRIM.Trim(charToTrim); //Se realiza el TRIM a result.Eliminando espacios al inicio y al final.
                                            phoneW = result.Split(' ');
                                            result = "";
                                            for (int w = 0; w < phoneW.Length; w++)
                                            {
                                                if (phoneW[w] != "")
                                                {
                                                    result = result + phoneW[w].ToString() + " ";
                                                }
                                            }
                                            if (result.Length < 16)//Se verifica que la longitud sea menos 16 para añadir espacios en blanco. Y no desfasar ningun campo.
                                            {
                                                accountMaster.WorkPhone = result.PadRight(16);//Se añaden espacios.
                                            }
                                            else
                                            {
                                                accountMaster.WorkPhone = result.Substring(0, 16);//O en su defecto, se toma solo al sub-cadena de los primeros 16 caracteres
                                            }
                                            break;
                                        } //FIN. If Para comprobar H-Home
                                    }
                                    else
                                    {
                                        MessageBox.Show("La cuenta: " + resultsPlacement.caseInfoList[i].accountInfoList[0].demographics.accountNumber.ToString() + " No tiene un TypeCode válido para phones", "Algo falló", MessageBoxButtons.OK);
                                    }
                                } //FIN. If WORKPHONE
                            } //FIN. CICLO-FOR WORKPHONE
                              //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
                        } // FIN If Phones[]
                          //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
                          //BIRTHDATE //  RUTA: resultsPlacement->caseInfoList[i]->accountInfoList[0]->demographics->birthDate
                        if (resultsPlacement.caseInfoList[i].accountInfoList[0].demographics.birthDate != null) //If BirthDate. INICIO
                        {
                            if (resultsPlacement.caseInfoList[i].accountInfoList[0].demographics.birthDate.ToString().Length < 8) // DEBE SER LONGITUD 8
                            {
                                accountMaster.BirthDate = resultsPlacement.caseInfoList[i].accountInfoList[0].demographics.birthDate.ToString().PadRight(8);
                            }
                            else
                            {
                                accountMaster.BirthDate = Convert.ToDateTime(resultsPlacement.caseInfoList[i].accountInfoList[0].demographics.birthDate).ToString("yyyyMMdd");
                            }
