                    } // FIN. If demographics
                      //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
                    if (resultsPlacement.caseInfoList[i].accountInfoList[0].employer != null) // If Employer. INICIO
                    {
                        //EMPLOYERSNAME //  RUTA: resultsPlacement->caseInfoList[i]->accountInfoList[0]->employer->name
                        if (resultsPlacement.caseInfoList[i].accountInfoList[0].employer.name != null)//If EmployersName. INICIO
                        {
                            string token = resultsPlacement.caseInfoList[i].accountInfoList[0].employer.name.ToString();//Se agrega por falla en el PLCMNT por caracteres raros- Angie Reyna 10/Feb/2020
                            accountMaster.EmployersName = Regex.Replace(token, @"[^a-zA-z0-9 ]+", " ").PadRight(40).Substring(0, 40);
                        } // FIN. If EmployersName
                          //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
                          //EMPLOYERSADDRESS //  RUTA: resultsPlacement->caseInfoList[i]->accountInfoList[0]->employer->address
                        if (resultsPlacement.caseInfoList[i].accountInfoList[0].employer.address != null) //AddressLine1 Vive dentro de address. Pero esto no se ha especificado.
                        {
                            if (resultsPlacement.caseInfoList[i].accountInfoList[0].employer.address.addressLine1 != null) //If EmployersAddress. INICIO
                            {
                                string token = resultsPlacement.caseInfoList[i].accountInfoList[0].employer.address.addressLine1.ToString();
                                accountMaster.EmployersAddress = Regex.Replace(token, @"[^a-zA-z0-9 ]+", " ").PadRight(40).Substring(0, 40);
                            } //FIN. If EmployersAddress->addressLine1
                              //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
                        }// FIN. If EmployersAddress
                         //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
                    }//FIN. If Employer
                     //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
                    if (resultsPlacement.caseInfoList[i].accountInfoList[0].productDetails != null) //If ProductDetails. INICIO
                    {
                        if (resultsPlacement.caseInfoList[i].accountInfoList[0].productDetails.amexProductCode != null) //If ProductCode. INICIO
                        {
                            if (resultsPlacement.caseInfoList[i].accountInfoList[0].productDetails.amexProductCode.ToString().Length < 4) //DEBE SER LONGITUD 4
                            {
                                accountMaster.ProductCode = resultsPlacement.caseInfoList[i].accountInfoList[0].productDetails.amexProductCode.ToString().PadRight(4);
                            }
                            else
                            {
                                accountMaster.ProductCode = resultsPlacement.caseInfoList[i].accountInfoList[0].productDetails.amexProductCode.ToString().Substring(0, 4);
                            }
                        } // FIN. If ProductCode
                          //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
                    } // FIN. If ProductDetails
                      //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
                } //FIN. If accountInfoList[]
                  //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
            } //FIN. If CaseInfoList[]
              //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
            return accountMaster;
        } //FIN. ValidacionAccountMaster
