        public XRecord validacionXPO(int i)
        {
            XRecord xrecord = new XRecord();
            if (resultsPlacement.caseInfoList != null)
            {
                /////////////////////////////ACCOUNTNUMBER
                if (resultsPlacement.caseInfoList != null)
                {
                    if (resultsPlacement.caseInfoList[i].accountInfoList != null)
                    {
                        if (((xrecord.AccountNumber == null || xrecord.AccountNumber == "                    ") || xrecord.AccountNumber == "                    ") && resultsPlacement.caseInfoList[i].accountInfoList[0].accountNumber != null)
                        {
                            if (resultsPlacement.caseInfoList[i].accountInfoList[0].accountNumber.Length < 20)
                            {
                                xrecord.AccountNumber = resultsPlacement.caseInfoList[i].accountInfoList[0].accountNumber.ToString().PadRight(20);
                            }
                            else
                            {
                                xrecord.AccountNumber = resultsPlacement.caseInfoList[i].accountInfoList[0].accountNumber.ToString().Substring(0, 20);
                            }
                        }
                        if ((xrecord.AccountNumber == null || xrecord.AccountNumber == "                    ") && resultsPlacement.caseInfoList[i].accountInfoList[0].accountDetails != null)
                        {
                            if (resultsPlacement.caseInfoList[i].accountInfoList[0].accountDetails.accountNumber != null)
                            {
                                if (resultsPlacement.caseInfoList[i].accountInfoList[0].accountDetails.accountNumber.Length < 20)
                                {
                                    xrecord.AccountNumber = resultsPlacement.caseInfoList[i].accountInfoList[0].accountDetails.accountNumber.ToString().PadRight(20);
                                }
                                else
                                {
                                    xrecord.AccountNumber = resultsPlacement.caseInfoList[i].accountInfoList[0].accountDetails.accountNumber.ToString().Substring(0, 20);
                                }
                            }
                        }
                        if ((xrecord.AccountNumber == null || xrecord.AccountNumber == "                    ") && resultsPlacement.caseInfoList[i].accountInfoList[0].account != null)
                        {
                            if (resultsPlacement.caseInfoList[i].accountInfoList[0].account.accountNumber != null)
                            {
                                if (resultsPlacement.caseInfoList[i].accountInfoList[0].account.accountNumber.Length < 20)
                                {
                                    xrecord.AccountNumber = resultsPlacement.caseInfoList[i].accountInfoList[0].account.accountNumber.ToString().PadRight(20);
                                }
                                else
