        public MasterRecord validacionMasterRecord(int i)
        {
            MasterRecord masterrecord = new MasterRecord();
            //////////////
            if (resultsPlacement.caseInfoList[i].accountInfoList != null)
            {
                if (resultsPlacement.caseInfoList[i].accountInfoList[0].treatments != null)
                {
                    bool ContadorY = false;
                    bool ContadorN = false;
                    for (int ii = 0; ii < resultsPlacement.caseInfoList[i].accountInfoList[0].treatments.Count; ii++)
                    {
                        if (resultsPlacement.caseInfoList[i].accountInfoList[0].treatments[ii].treatmentProgram == "AC PGRM")
                        {
                            string Valor = resultsPlacement.caseInfoList[i].accountInfoList[0].treatments[ii].treatmentEligibility;
                            if (Valor == "Y" || Valor == "N")
                            {
                                if (Valor == "Y")
                                {
                                    if (!ContadorY)
                                    {
                                        if (!ContadorN)
                                        {
                                            masterrecord.ACProgram = resultsPlacement.caseInfoList[i].accountInfoList[0].treatments[ii].treatmentEligibility.PadRight(8);
                                        }
                                        else
                                            masterrecord.ACProgram = (masterrecord.ACProgram.Trim() + resultsPlacement.caseInfoList[i].accountInfoList[0].treatments[ii].treatmentEligibility).PadRight(8);
                                        ContadorY = true;
                                    }
                                }
                                else if (Valor == "N")
                                {
                                    if (!ContadorN)
                                    {
                                        if (!ContadorY)
                                        {
                                            masterrecord.ACProgram = resultsPlacement.caseInfoList[i].accountInfoList[0].treatments[ii].treatmentEligibility.PadRight(8);
                                        }
                                        else
                                            masterrecord.ACProgram = (masterrecord.ACProgram.Trim() + resultsPlacement.caseInfoList[i].accountInfoList[0].treatments[ii].treatmentEligibility).PadRight(8);
                                        ContadorN = true;
                                    }
                                }
                                else
                                {
                                    if (!ContadorN)
                                    {
                                        if (!ContadorY)
                                        {
                                            masterrecord.ACProgram = "        ";
                                        }
                                    }
                                }
                            }
                            else
                            {
                                if (!ContadorN)
                                {
                                    if (!ContadorY)
                                    {
                                        masterrecord.ACProgram = "        ";
                                    }
                                }
                            }
                        }
                        else
                        {
                            if (!ContadorN)
                            {
                                if (!ContadorY)
