                    else
                    {
                        if (resultsPlacement.caseInfoList[i].accountInfoList[0].collectionRiskScore != null)//If collectionRiskScore. INICIO
                        {
                            //lendingPayToCurrrentScore // RUTA: resultsPlacement->caseInfoList[i]->accountInfoList[0]->collectionRiskScore->lendingPayToCurrrentScore
                            if (resultsPlacement.caseInfoList[i].accountInfoList[0].collectionRiskScore.lendingPayToCurrrentScore != null)//if lendingPayToCurrrentScore. INICIO
