                                    masterrecord.OldLendingScore = DoFormat(resultsPlacement.caseInfoList[i].accountInfoList[0].collectionRiskScore.lendingPayToCurrrentScore.ToString()).Replace(".", "").PadRight(11).Substring(0, 11);
                                }
                            }//FIN. If lendingPayToCurrrentScore
                             ////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
                        }
                    }
                    ////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
                    if (resultsPlacement.caseInfoList[i].accountInfoList[0].strategyInfo != null)//If strategyInfo. INICIO
                    {
                        //SPEEDTOPAYMODEL // RUTA: resultsPlacement->caseInfoList[i]->accountInfoList[0]->strategyInfo->speedToPayModel
                        if (resultsPlacement.caseInfoList[i].accountInfoList[0].strategyInfo.speedToPayModel != null)//if speedToPayModel. INICIO
                        {
