                            }
                        }//FIN. If speedToPayModel
                         ////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
                    }//FIN. If strategyInfo
                     ////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
                }// FIN. If accountInfoList[]
                 ////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
            }// FIN. If caseInfoList[]
             ////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
            return masterrecord;
