        public History ValidacionHistory(int i)
        {
            History history = new History();
            if (resultsPlacement.caseInfoList != null)
            {
                if (resultsPlacement.caseInfoList != null)
                {
                    if (resultsPlacement.caseInfoList[i].accountInfoList != null)
                    {
                        if (((history.AccountNumber == null || history.AccountNumber == "                    ") || history.AccountNumber == "                    ") && resultsPlacement.caseInfoList[i].accountInfoList[0].accountNumber != null)
                        {
                            if (resultsPlacement.caseInfoList[i].accountInfoList[0].accountNumber.Length < 20)
                            {
                                history.AccountNumber = resultsPlacement.caseInfoList[i].accountInfoList[0].accountNumber.ToString().PadRight(20);
                            }
                            else
                            {
                                history.AccountNumber = resultsPlacement.caseInfoList[i].accountInfoList[0].accountNumber.ToString().Substring(0, 20);
                            }
                        }
                        if ((history.AccountNumber == null || history.AccountNumber == "                    ") && resultsPlacement.caseInfoList[i].accountInfoList[0].accountDetails != null)
                        {
                            if (resultsPlacement.caseInfoList[i].accountInfoList[0].accountDetails.accountNumber != null)
                            {
                                if (resultsPlacement.caseInfoList[i].accountInfoList[0].accountDetails.accountNumber.Length < 20)
                                {
                                    history.AccountNumber = resultsPlacement.caseInfoList[i].accountInfoList[0].accountDetails.accountNumber.ToString().PadRight(20);
                                }
                                else
                                {
                                    history.AccountNumber = resultsPlacement.caseInfoList[i].accountInfoList[0].accountDetails.accountNumber.ToString().Substring(0, 20);
                                }
                            }
                        }
                        if ((history.AccountNumber == null || history.AccountNumber == "                    ") && resultsPlacement.caseInfoList[i].accountInfoList[0].account != null)
                        {
                            if (resultsPlacement.caseInfoList[i].accountInfoList[0].account.accountNumber != null)
                            {
                                if (resultsPlacement.caseInfoList[i].accountInfoList[0].account.accountNumber.Length < 20)
                                {
                                    history.AccountNumber = resultsPlacement.caseInfoList[i].accountInfoList[0].account.accountNumber.ToString().PadRight(20);
                                }
                                else
                                {
                                    history.AccountNumber = resultsPlacement.caseInfoList[i].accountInfoList[0].account.accountNumber.ToString().Substring(0, 20);
                                }
                            }
                        }
                        if ((history.AccountNumber == null || history.AccountNumber == "                    ") && resultsPlacement.caseInfoList[i].accountInfoList[0].agencyAssignment != null)
                        {
                            if (resultsPlacement.caseInfoList[i].accountInfoList[0].agencyAssignment.accountNumber != null)
                            {
                                if (resultsPlacement.caseInfoList[i].accountInfoList[0].agencyAssignment.accountNumber.Length < 20)
                                {
                                    history.AccountNumber = resultsPlacement.caseInfoList[i].accountInfoList[0].agencyAssignment.accountNumber.ToString().PadRight(20);
                                }
                                else
                                {
                                    history.AccountNumber = resultsPlacement.caseInfoList[i].accountInfoList[0].agencyAssignment.accountNumber.ToString().Substring(0, 20);
                                }
                            }
                        }
                    }
                }
                history.RecordType = "H";
                history.SequenceNumber = "00";
                for (int ii = 0; ii < 13; ii++)
                {
                    string date = DateTime.Now.ToString("yyyyMMdd");
                    string note = "                                        "; //40 Espacios
                    history.Date_NoteLine = history.Date_NoteLine + date + note;
                }
                history.Filler = "                                                ";
                history.AgencyCode = "    ";
                history.FormatCode = "B";
            }
            return history;
        }
