                                comaker.FirstName = Regex.Replace(token, @"[^a-zA-z0-9 =]+", " ").PadRight(20).Substring(0, 20); //DEBE SER LONGITUD 20
                            } //FIN. If FirstName
                              //////////////////////////////////////////////////////////////////////////////////////
                              //LASTNAME// RUTA: resultsPlacement->caseInfoList[i]->accountInfoList[0]->relatedPersonList->relatedPersonDetailsList[ii]->lastName
                            if (resultsPlacement.caseInfoList[i].accountInfoList[0].relatedPersonList.relatedPersonDetailsList[ii].lastName != null) //If lastName INICIO.
                            {
                                string token = resultsPlacement.caseInfoList[i].accountInfoList[0].relatedPersonList.relatedPersonDetailsList[ii].lastName.ToString();
                                comaker.LastName = Regex.Replace(token, @"[^a-zA-z0-9 =]+", " ").PadRight(20).Substring(0, 20); //DEBE SER LONGITUD 20
                            } //FIN. If LastName
                              //////////////////////////////////////////////////////////////////////////////////////
                            if (resultsPlacement.caseInfoList[i].accountInfoList[0].relatedPersonList.relatedPersonDetailsList[ii].phoneList != null)
                            {
                                //HOMEPHONE Y WORKPHONE // RUTA: resultsPlacement->caseInfoList[i]->accountInfoList[0]->demographics->phones[]->number
                                int tamphones = resultsPlacement.caseInfoList[i].accountInfoList[0].relatedPersonList.relatedPersonDetailsList[ii].phoneList.Count();
                                string[] phoneH;
                                string[] phoneW;
                                char[] charToTrim = { ' ' }; //Se definen los caracteres a eliminar. En este caso son espacios.
                                for (int n = 0; n < tamphones; n++)//Ciclo FOR, para revisar toda la lista phones[] En busca de un HomePhone.
                                {
                                    if (resultsPlacement.caseInfoList[i].accountInfoList[0].relatedPersonList.relatedPersonDetailsList[ii].phoneList[n].number != null)//If HomePhone INICIO.
                                    {
                                        if (resultsPlacement.caseInfoList[i].accountInfoList[0].relatedPersonList.relatedPersonDetailsList[ii].phoneList[n].typeCode.ToString() == "H-HOME") //Si posee el codigo H-Home es un HomePhone.
                                        {
