                                            string result = HomePhoneTRIM.Trim(charToTrim); //Se realiza el TRIM a result.Eliminando espacios al inicio y al final.
                                            phoneH = result.Split(' ');
                                            result = "";
                                            for (int h = 0; h < phoneH.Length; h++)
                                            {
                                                if (phoneH[h] != "")
                                                {
                                                    result = result + phoneH[h].ToString() + " ";
                                                }
                                            }
                                            if (result.Length < 16)//Se verifica que la longitud sea menos 16 para añadir espacios en blanco. Y no desfasar ningun campo.
                                            {
                                                comaker.HomePhone = result.PadRight(16);//Se añaden espacios.
                                            }
                                            else
                                            {
                                                comaker.HomePhone = result.Substring(0, 16);//O en su defecto, se toma solo al sub-cadena de los primeros 16 caracteres
                                            }
                                            break;
                                        } //FIN. If Para comprobar H-Home
                                    } //FIN. If HOMEPHONE
                                      ////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
                                } //FIN. CICLO-FOR HOMEPHONE
                                  //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
                                for (int nn = 0; nn < tamphones; nn++)//Ciclo FOR, para revisar toda la lista phones[] En busca de un WorkPhone.
                                {
                                    if (resultsPlacement.caseInfoList[i].accountInfoList[0].relatedPersonList.relatedPersonDetailsList[ii].phoneList[nn].number != null)//If WorkPhone INICIO.
                                    {
                                        if (resultsPlacement.caseInfoList[i].accountInfoList[0].relatedPersonList.relatedPersonDetailsList[ii].phoneList[nn].typeCode.ToString() == "B-BUS") //Si posee el codigo H-Home es un WorkPhone.
                                        {
                                            string WorkPhoneTRIM = resultsPlacement.caseInfoList[i].accountInfoList[0].relatedPersonList.relatedPersonDetailsList[ii].phoneList[nn].number.ToString();//Almacenamos, lo que haya en number. En una string result.
                                            string result = WorkPhoneTRIM.Trim(charToTrim); //Se realiza el TRIM a result.Eliminando espacios al inicio y al final.
                                            phoneW = result.Split(' ');
                                            result = "";
                                            for (int w = 0; w < phoneW.Length; w++)
                                            {
                                                if (phoneW[w] != "")
                                                {
                                                    result = result + phoneW[w].ToString() + " ";
                                                }
                                            }
                                            if (result.Length < 16)//Se verifica que la longitud sea menos 16 para añadir espacios en blanco. Y no desfasar ningun campo.
                                            {
                                                comaker.WorkPhone = result.PadRight(16);//Se añaden espacios.
                                            }
                                            else
                                            {
                                                comaker.WorkPhone = result.Substring(0, 16);//O en su defecto, se toma solo al sub-cadena de los primeros 16 caracteres
                                            }
                                            break;
                                        } //FIN. If Para comprobar H-Home
                                    } //FIN. If WORKPHONE
                                      //////////////////////////////////////////////////////////////////////////////
                                } //FIN. CICLO-FOR WORKPHONE
                                  //////////////////////////////////////////////////////////////////////////////////
                            }//FIN. If phoneList[]
                             //////////////////////////////////////////////////////////////////////////////////////
                        }//FIN. If RelatedPersonDetailList
                         //////////////////////////////////////////////////////////////////////////////////////////
                    }//FIN. If RelatedPersonList
                     //////////////////////////////////////////////////////////////////////////////////////////////
                } //FIN. If AccountInfoList[].
                  //////////////////////////////////////////////////////////////////////////////////////////////////
            } //FIN. If CaseInfoList[].
              //////////////////////////////////////////////////////////////////////////////////////////////////////
            return comaker;
        } //FIN. ValidacionComaker
          //////////////////////////////////////////////////////////////////////////////////////////////////////////
        #endregion ValidaciónC
        #endregion Validaciones

        /// <summary>
        /// Se definen las 2 clases y los 3 métodos utilizados para la generación del archivo de asignación
        /// del updatesOB; el archivo .mt
        /// Se utilizan 3 métodos para los 3 tipos diferentes de validaciones que componen el archivo .mt
        /// </summary>
        #region GenerarMT - UPDATESOB
        public class ArchivoMTFIinancial
        {
            public string DATE = "        "; //8 Espacios
            public string TIME = "    "; //4 Espacios
            public string ACCOUNTNUMBER = "                    ";//20 Espacios
            public string TRANSACTION_CODE = "  "; //2 Espacios 
            public string TRANSACTION_AMOUNT = "          "; //10 Espacios
            public string FLAG = " "; // 1 Espacio
            public string SELF = " ";//1 Espacio
            public string DESCRIPCION = "                    "; //20 Espacios
            public string PAYMENT = "          ";//10 Espacios
            public string PERCENT = "    "; //4 Espacios
            public string FLAG_INT_EXT = " "; //1 Espacio
            public string RECOVERER_CODE = "    ";//4 Espacios
            public string RECOVERER_ID = "        "; //8Espacios
            public string LOAN_CODE = "    "; //4 Espacios
            public string FILL = "   "; //3 Espacios
            public string TRANSACCIONID = "                         ";//25 Espacios

        }
        public class ArchivoMT
        {
            public string DATE = "        ";
            public string TIME = "    ";
            public string ACCOUNTNUMBER = "                    ";
            public string TRANSACTION_CODE = "  ";
            public string FIELD_CODE = "      ";
            public string NEW_VALUE = "                                        ";
            public string FLAG = " ";
            public string RECOVERER_CODE = "    ";
            public string RECOVERER_ID = "        ";
            public string LOAN_CODE = "    ";
            public string FILL = "   ";
        }
        public bool GenerarMT(string RutaCompleta, string archivo, Ent_Json_Update.RootObject resultsUpdate, int seqNo)
        {
            ArchivoMTFIinancial archivoMT;
            string archivoSB_ = Path.GetDirectoryName(RutaCompleta);
            string ruta_ = archivo + "\\JSONMT" + seqNo + "-" + DateTime.Now.ToString("dd-MM-yyyy HHmmss") + ".mt ";
            string rutaUltimoIndice = archivo + "\\UltimoIndice" + DateTime.Now.ToString("dd-MM-yyyy HHmmss") + ".txt";
            List<int?> LastTrans = new List<int?>();
            using (CYBEREntities DB = new CYBEREntities())
            {
                LastTrans = DB.spSelectSertecUltimaTransaction().ToList();
            }
            File.WriteAllText(rutaUltimoIndice, LastTrans[0].ToString());

            File.WriteAllText(ruta_, "");
            //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
            if (resultsUpdate.accountList != null)
            {
                IList<string> Unicos = new List<string>(); //Se crea una lista de cadenas llamada Unicos, donde se almacenaran las cadenas que se plasmarán en el MT
                for (int i = 0; i < resultsUpdate.accountList.Count; i++)
                {
                    if (resultsUpdate.accountList[i].currentAgencyId != null)
                    {
                        using (CYBEREntities DB = new CYBEREntities())
                        {
                            DB.spInsertAmexBitacora(resultsUpdate.accountList[i].accountNumber, resultsUpdate.accountList[i].currentAgencyId, "", DateTime.Now, resultsUpdate.header.balancingSeqNo.ToString().PadLeft(4, '0') + " UPDATESOB", 3);
                        }
                    }
                    if (resultsUpdate.accountList[i].currentBalance != null)
                    {
                        StringBuilder SB_ = new StringBuilder(); //Se crea un objeto de la clase StringBuilder llamado SB_ para poder escribir en el archivo MT.
                        archivoMT = new ArchivoMTFIinancial(); //Se crea un objeto de la clase ArchivoMTFIinancial, para poder asignarle los valores de los atributos que se obtendrán en el siguiente paso.
                        archivoMT = ValidacionArchivoMTCuenta_(i, resultsUpdate.accountList[i]); //Se inicializa el archivo tipo MT, y se asignan sus valores en blanco. 
                        //Posteriormente, se obtienen los valores que sustituiran esos campos en blanco.
                        string cade = Cadena(8, null, null, null, null, null, null, null, archivoMT, null, null); //Se concatena todo lo obtenido con base al switch caso 8 del método Cadena().
                        if (!Unicos.Contains(cade)) //Si la lista no contiene la cadena que acabamos de concatenar...
                        {
                            Unicos.Add(cade);//Se añadirá como un nuevo elemento a la lista.
                            SB_.AppendLine(cade);//Se agregará la cadena al StringBuilder SB_
                            File.AppendAllText(ruta_, SB_.ToString()); //Y se escribirá en el archivo que se creo en la ruta ruta_
                            using (CYBEREntities DB = new CYBEREntities())
                            {
                                DB.spInsertAmexBitacora(archivoMT.ACCOUNTNUMBER.Trim(), "", "CURRENT BALANCE " + resultsUpdate.accountList[i].currentBalance.ToString(), DateTime.Now, resultsUpdate.header.balancingSeqNo.ToString().PadLeft(4, '0') + " UPDATESOB", 1);
                            }
                        }
                    }

                }

            }
            /////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
            if (resultsUpdate.treatmentList != null)
            {
                for (int i = 0; i < resultsUpdate.treatmentList.Count; i++)
                {
                    if (resultsUpdate.treatmentList[i].treatmentProgram != null)
                    {
                        if (resultsUpdate.treatmentList[i].treatmentProgram == "REINST" || resultsUpdate.treatmentList[i].treatmentProgram == "OASIS")
                        {
                            StringBuilder SB_ = new StringBuilder();
                            archivoMT = new ArchivoMTFIinancial();
                            archivoMT = ValidacionArchivoMTTreatment(i, resultsUpdate.treatmentList[i]);
                            string cade = Cadena(8, null, null, null, null, null, null, null, archivoMT, null, null);
                            SB_.AppendLine(cade);
                            File.AppendAllText(ruta_, SB_.ToString());
                            for (int ii = 0; ii < resultsUpdate.accountList.Count; ii++)
                            {
                                if (archivoMT.ACCOUNTNUMBER.Trim() == resultsUpdate.accountList[ii].accountNumber && resultsUpdate.accountList[ii].currentBalance != null) //MODIFICAR ESTO, SE ESTAN PERDIENDO DATOS EN LA BITACORA
                                {
                                    using (CYBEREntities DB = new CYBEREntities())
                                    {
                                        DB.spInsertAmexBitacora(archivoMT.ACCOUNTNUMBER.Trim(), "", "TREATMENT " + archivoMT.RECOVERER_ID + resultsUpdate.accountList[ii].currentBalance.ToString(), DateTime.Now, resultsUpdate.header.balancingSeqNo.ToString().PadLeft(4, '0') + " UPDATESOB", 1);
                                    }
                                    break;
                                }
                            }
                        }
                    }
                }
            }
            /////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

            if (resultsUpdate.financialTransactionDetailsList != null)
            {
                IList<string> Unicos = new List<string>();
                for (int i = 0; i < resultsUpdate.financialTransactionDetailsList.Count; i++)
                {


                    if (resultsUpdate.financialTransactionDetailsList[i].transactions != null)
                    {
                        for (int ii = 0; ii < resultsUpdate.financialTransactionDetailsList[i].transactions.Count; ii++)
                        {
                            ValidacionMT = true;


                            IList<int?> Valor = new List<int?>();
                            using (CYBEREntities DB = new CYBEREntities())
                            {
                                Valor = DB.spSelectAmexTablaTrans(resultsUpdate.financialTransactionDetailsList[i].transactions[ii].transactionDate, Convert.ToDecimal(resultsUpdate.financialTransactionDetailsList[i].transactions[ii].transactionAmount), resultsUpdate.financialTransactionDetailsList[i].transactions[ii].accountNumber, resultsUpdate.financialTransactionDetailsList[i].transactions[ii].transactionId).ToList();
                                //Este Stored procedure regresa un valor 0 o un valor1. Dependiendo de si se cumplen o no las condiciones del SP.
                            }
                            if (ExcepcionUPDATESOB.Checked)//Este check no se usa a dia de hoy.
                            {
                                StringBuilder SB_ = new StringBuilder();
                                archivoMT = new ArchivoMTFIinancial();
                                archivoMT = ValidacionArchivoMT_(i, ii, resultsUpdate);
                                if (ValidacionMT) //ValidacionMT tendrá un valor falso, cuando no se haya encontrado el segmento de la cuenta. En ValidacionArchivoMT_
                                {
                                    if (resultsUpdate.financialTransactionDetailsList[i].transactions[ii].transactionCode != "99")
                                    {
                                        string TransaccionID = resultsUpdate.financialTransactionDetailsList[i].transactions[ii].transactionId; //Obtiene el transactionID del elemento actual de transactions en el JSON y lo almacena en una variable.
                                        string cade = Cadena(8, null, null, null, null, null, null, null, archivoMT, null, null); //Concatena todos los elementos del objeto archivoMT y almacena la concatenación en la variable cade
                                        if (!Unicos.Contains(TransaccionID)) //Se pregunta si el transactionId actual que se este procesando, existe ya en la lista de cadenas "Unicos". En caso de que no exista se procede, si existe ya. Se ignoran las siguientes instrucciones
                                        {
                                            Unicos.Add(TransaccionID);
                                            SB_.AppendLine(cade);
                                            File.AppendAllText(ruta_, SB_.ToString());
                                            using (CYBEREntities DB = new CYBEREntities())
                                            {
                                                DB.spInsertAmexBitacora(archivoMT.ACCOUNTNUMBER.Trim(), "", archivoMT.TRANSACTION_CODE.Trim() + " " + archivoMT.DESCRIPCION, DateTime.Now, resultsUpdate.header.balancingSeqNo.ToString().PadLeft(4, '0') + " UPDATESOB", 1);
                                            }
                                        }
                                    }
                                }
                            }
                            else
                            {
                                if (Valor[0] == 0)
                                {
                                    StringBuilder SB_ = new StringBuilder();
                                    archivoMT = new ArchivoMTFIinancial();
                                    archivoMT = ValidacionArchivoMT_(i, ii, resultsUpdate);
                                    if (ValidacionMT) //ValidacionMT tendrá un valor falso, cuando no se haya encontrado el segmento de la cuenta. En ValidacionArchivoMT_
                                    {
                                        if (resultsUpdate.financialTransactionDetailsList[i].transactions[ii].transactionCode != "99")
                                        {
                                            string TransaccionID = resultsUpdate.financialTransactionDetailsList[i].transactions[ii].transactionId; //Obtiene el transactionID del elemento actual de transactions en el JSON y lo almacena en una variable.
                                            string cade = Cadena(8, null, null, null, null, null, null, null, archivoMT, null, null); //Concatena todos los elementos del objeto archivoMT y almacena la concatenación en la variable cade
                                            if (!Unicos.Contains(TransaccionID)) //Se pregunta si el transactionId actual que se este procesando, existe ya en la lista de cadenas "Unicos". En caso de que no exista se procede, si existe ya. Se ignoran las siguientes instrucciones
                                            {
                                                Unicos.Add(TransaccionID); //Se añade el trnasaction ID a la lista de únicos en caso de que no exista previamente. Para evitar duplicidad de la información.
                                                SB_.AppendLine(cade);//Se crea una linea de texto con lo obtenido durante el procesamiento de la entidad transactions.
                                                File.AppendAllText(ruta_, SB_.ToString()); //Se anexa la linea generada en la instrucción anterior al archivo .mt que se esta generando.
                                                using (CYBEREntities DB = new CYBEREntities())
                                                {
                                                    DB.spInsertAmexBitacora(archivoMT.ACCOUNTNUMBER.Trim(), "", archivoMT.TRANSACTION_CODE.Trim() + " " + archivoMT.DESCRIPCION, DateTime.Now, resultsUpdate.header.balancingSeqNo.ToString().PadLeft(4, '0') + " UPDATESOB", 1);
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            bool AlmacenarBase = true;
            return AlmacenarBase;
        }
        public ArchivoMTFIinancial ValidacionArchivoMTTreatment(int i, TreatmentList treatmentList)
        {
            ArchivoMTFIinancial archivoMT = new ArchivoMTFIinancial();
            archivoMT.TRANSACTION_CODE = "MT";
            archivoMT.FLAG_INT_EXT = "I";
            switch (treatmentList.treatmentProgram)
            {
                case "REINST":
                    archivoMT.RECOVERER_ID = "MXREINST".PadRight(8);
                    archivoMT.TRANSACTION_AMOUNT = "X00AMB".PadRight(10);
                    break;
                case "OASIS":
                    archivoMT.RECOVERER_ID = "MXOASIS".PadRight(8);
                    archivoMT.TRANSACTION_AMOUNT = "X00OAA".PadRight(10);
                    break;
                default:
                    break;
            }
            archivoMT.DATE = Convert.ToDateTime(treatmentList.updateDate).ToString("yyyyMMdd");
            archivoMT.TIME = Convert.ToDateTime(treatmentList.updateDate).ToString("hhmm");
            archivoMT.ACCOUNTNUMBER = treatmentList.accountNumber.ToString().PadRight(20);
            List<spSelectProducto_Result> Resultado = new List<spSelectProducto_Result>();
            using (CYBEREntities DB = new CYBEREntities())
            {
                Resultado = DB.spSelectProducto(treatmentList.accountNumber).ToList();
            }
            if (Resultado.Count != 0)
            {
                archivoMT.RECOVERER_CODE = Resultado[0].TBAXATCURRENTAGENCYID.Substring(2, 4);
                archivoMT.LOAN_CODE = Resultado[0].TBAXATPRODUCTCODE.ToString().PadRight(4);
            }
            //else { MessageBox.Show("La cuenta: " + accountList.accountNumber.ToString() + "No existe en la base", "Algo falló", MessageBoxButtons.OK); }
            return archivoMT;
        }
        public ArchivoMTFIinancial ValidacionArchivoMTCuenta_(int i, AccountList accountList)
        {
            ArchivoMTFIinancial archivoMT = new ArchivoMTFIinancial(); //Se crea un objeto de la clase ArchivoMTFIinancial. Con los atributos correspondientes, en blanco.
            archivoMT.TRANSACTION_CODE = "66"; //Se comienzan a llenar los atributos con los valores requeridos por el MT.
            archivoMT.FLAG_INT_EXT = "I";
            archivoMT.RECOVERER_ID = "BATCH".PadRight(8);
            archivoMT.TRANSACTION_AMOUNT = DoFormat(accountList.currentBalance.ToString()).Replace(".", "").PadLeft(10, '0');
            archivoMT.DESCRIPCION = "ACT CURR".PadRight(20);
            archivoMT.DATE = Convert.ToDateTime(accountList.updateDate).ToString("yyyyMMdd");
            archivoMT.TIME = Convert.ToDateTime(accountList.updateDate).ToString("hhmm");
            archivoMT.ACCOUNTNUMBER = accountList.accountNumber.ToString().PadRight(20);
            List<spSelectProducto_Result> Resultado = new List<spSelectProducto_Result>(); //Se crea un nuevo objeto de tipo Lista spSelectProducto_Result
            using (CYBEREntities DB = new CYBEREntities()) //Se crea la conexión a la BD
            {
                Resultado = DB.spSelectProducto(accountList.accountNumber).ToList(); //Y se manda llamar al SP spSelectProducto. El resultado se guarda en la lista que acabamos de crear.
            }
            if (Resultado.Count != 0) //Si obtiene algo. Asignará el RECOVERER CODE y el LOAN CODE con base a lo obtenido. 
            {
                archivoMT.RECOVERER_CODE = Resultado[0].TBAXATCURRENTAGENCYID.Substring(2, 4);
                archivoMT.LOAN_CODE = Resultado[0].TBAXATPRODUCTCODE.ToString().PadRight(4);
            }
            //else { MessageBox.Show("La cuenta: " + accountList.accountNumber.ToString() + "No existe en la base", "Algo falló", MessageBoxButtons.OK); }
            return archivoMT;
        }
        private ArchivoMTFIinancial ValidacionArchivoMT_(int i, int ii, Ent_Json_Update.RootObject MT)
        {
            ArchivoMTFIinancial archivoMT = new ArchivoMTFIinancial();
            if (MT.financialTransactionDetailsList[i].transactions[ii].transactionCode != "99") //Si el codigo de transacción, es diferente a 99
            {
                switch (MT.financialTransactionDetailsList[i].transactions[ii].transactionCode)
                {
                    case "50":
                        archivoMT.TRANSACTION_CODE = "50";
                        break;
                    case "11":
                        archivoMT.TRANSACTION_CODE = "11";
                        break;
                    case "12":
                        archivoMT.TRANSACTION_CODE = "12";
                        break;
                    case "55":
                        archivoMT.TRANSACTION_CODE = "55";
                        break;
                    default:
                        archivoMT.TRANSACTION_CODE = "MT";
                        break;
                }
                archivoMT.FLAG_INT_EXT = "I";
                //archivoMT.RECOVERER_CODE = "PLHS";

                archivoMT.RECOVERER_ID = "BATCH".PadRight(8);

                if (MT.financialTransactionDetailsList[i].transactions[ii].transactionAmount != null)
                {
                    if (MT.financialTransactionDetailsList[i].transactions[ii].transactionCode == "50")
                    {
                        string g = (MT.financialTransactionDetailsList[i].transactions[ii].transactionAmount * -1).ToString().PadLeft(10, '0');
                        archivoMT.TRANSACTION_AMOUNT = DoFormat((MT.financialTransactionDetailsList[i].transactions[ii].transactionAmount * -1).ToString()).Replace(".", "").PadLeft(10, '0');
                        archivoMT.DESCRIPCION = "DIRECT PAYMENT".PadRight(20);
                    }
                    if (MT.financialTransactionDetailsList[i].transactions[ii].transactionCode == "11")
                    {
                        string g = (MT.financialTransactionDetailsList[i].transactions[ii].transactionAmount).ToString().PadLeft(10, '0');
                        archivoMT.TRANSACTION_AMOUNT = DoFormat((MT.financialTransactionDetailsList[i].transactions[ii].transactionAmount).ToString()).Replace(".", "").PadLeft(10, '0');
                        archivoMT.DESCRIPCION = "DEBIT ADJUSTMENT - O".PadRight(20);
                    }
                    if (MT.financialTransactionDetailsList[i].transactions[ii].transactionCode == "55")
                    {
                        string g = (MT.financialTransactionDetailsList[i].transactions[ii].transactionAmount).ToString().PadLeft(9, '0') + " ";
                        archivoMT.TRANSACTION_AMOUNT = DoFormat((MT.financialTransactionDetailsList[i].transactions[ii].transactionAmount).ToString()).Replace(".", "").PadLeft(9, '0') + " ";
                        archivoMT.DESCRIPCION = "NSF DIRECT".PadRight(20);
                    }
                    if (MT.financialTransactionDetailsList[i].transactions[ii].transactionCode == "12")
                    {
                        string g = (MT.financialTransactionDetailsList[i].transactions[ii].transactionAmount * -1).ToString().PadLeft(9, '0') + " ";
                        archivoMT.TRANSACTION_AMOUNT = DoFormat((MT.financialTransactionDetailsList[i].transactions[ii].transactionAmount * -1).ToString()).Replace(".", "").PadLeft(9, '0') + " ";
                        archivoMT.DESCRIPCION = "CREDIT ADJUSTMENT -".PadRight(20);
                    }
                }
                /////////////////////////////TRANSACTIONDATE
                if (MT.financialTransactionDetailsList[i].transactions[ii].transactionDate != null)
                {
                    archivoMT.DATE = Convert.ToDateTime(MT.financialTransactionDetailsList[i].transactions[ii].transactionDate).ToString("yyyyMMdd");
                    archivoMT.TIME = Convert.ToDateTime(MT.financialTransactionDetailsList[i].transactions[ii].transactionDate).ToString("hhmm");
                }
                /////////////////////////////ACCOUNTNUMBER
                if (MT.financialTransactionDetailsList[i].transactions[ii].accountNumber != null)
                {

                    if (MT.financialTransactionDetailsList[i].transactions[ii].accountNumber.ToString().Length < 20)
                        archivoMT.ACCOUNTNUMBER = MT.financialTransactionDetailsList[i].transactions[ii].accountNumber.ToString().PadRight(20);
                    else
                        archivoMT.ACCOUNTNUMBER = MT.financialTransactionDetailsList[i].transactions[ii].accountNumber.ToString().Substring(0, 20);
                }
                /////////////////////////////loancode
                if (MT.financialTransactionDetailsList[i].transactions[ii].processingStatus != null)
                {
                    if (MT.financialTransactionDetailsList[i].transactions[ii].processingStatus.ToString().Length < 4)
                        archivoMT.LOAN_CODE = MT.financialTransactionDetailsList[i].transactions[ii].processingStatus.ToString().PadRight(4);
                    else
                        archivoMT.LOAN_CODE = MT.financialTransactionDetailsList[i].transactions[ii].processingStatus.ToString().Substring(0, 4).PadRight(4);
                }
                //////////////TRANSACCION ID
                if (MT.financialTransactionDetailsList[i].transactions[ii].transactionId != null)
                {
                    if (MT.financialTransactionDetailsList[i].transactions[ii].transactionId.ToString().Length < 25)
                        archivoMT.TRANSACCIONID = MT.financialTransactionDetailsList[i].transactions[ii].transactionId.ToString().PadRight(25);
                    else
                        archivoMT.TRANSACCIONID = MT.financialTransactionDetailsList[i].transactions[ii].transactionId.ToString().Substring(0, 25).PadRight(25);
                }
                List<spSelectProducto_Result> Resultado = new List<spSelectProducto_Result>();
                using (CYBEREntities DB = new CYBEREntities())
                {
                    Resultado = DB.spSelectProducto(MT.financialTransactionDetailsList[i].transactions[ii].accountNumber).ToList();
                }
                if (Resultado.Count == 0)
                {
                    using (CYBEREntities DB = new CYBEREntities())
                    {
                        DB.spInsertAmexBitacora(archivoMT.ACCOUNTNUMBER.Trim(), "", "ERROR no existe cuenta", DateTime.Now, resultsUpdate.header.balancingSeqNo.ToString().PadLeft(4, '0') + " UPDATESOB", 1);
                        //ValidacionMT = false;
                        //ValidacionMTFINAL = false;
                        MessageBox.Show("CUIDADO, PARECE SER QUE LA CUENTA: " + archivoMT.ACCOUNTNUMBER.Trim() + " NO EXISTE", "ERROR DE CUENTA", MessageBoxButtons.OK);
                    }
                }
                else
                {
                    archivoMT.RECOVERER_CODE = Resultado[0].TBAXATCURRENTAGENCYID.Substring(2, 4);
                    archivoMT.LOAN_CODE = Resultado[0].TBAXATPRODUCTCODE.ToString().PadRight(4);
                }
            }
            return archivoMT;
        }
        #endregion GenerarMT - UPDATESOB

        /// <summary>
        /// Se define la clase ArchivoRecall, asi como el método necesario para la generación del archivo de asignación
        /// de los archivos RECALL.
        /// </summary>
        #region ArchivoRecall
        public class ArchivoRecall
        {
            public string DATE = "        ";
            public string TIME = "    ";
            public string ACCOUNTNUMBER = "                    ";
            public string TRANSACTION_CODE = "AR";
            public string FIELD_CODE = "RECALL";
            public string FILL = "                                        ";
            public string FLAG = " ";
            public string RECOVERER_CODE = "    ";
            public string RECOVERER_ID = "RMSAMX  ";
            public string LOAN_CODE = "    ";
            public string FILLER = "   ";
            //archivoRecall.DATE + archivoRecall.TIME + archivoRecall.ACCOUNTNUMBER + archivoRecall.TRANSACTION_CODE + archivoRecall.FIELD_CODE + archivoRecall.FILL + archivoRecall.FLAG + archivoRecall.RECOVERER_CODE + archivoRecall.RECOVERER_ID + archivoRecall.LOAN_CODE + archivoRecall.FILLER;
            //8+4+20+2+6+40+1+4+8+4+3
        }
        public ArchivoRecall ValidacionArchivoRecall(int i, Ent_Json_Recall.AccountRecallInfoList resultsRecall) //Función llamada en GenerarRecall
        {
            ArchivoRecall archivoRecall = new ArchivoRecall(); //se crea una nuevo objeto de la clase ArchivoRecall llamado archivoRecall, para poder asignarle las propiedades de la entidad resultsRecall que recibe la función.
            archivoRecall.DATE = Convert.ToDateTime(resultsRecall.agencyRecallDate).ToString("yyyyMMdd"); //Del nuevo objeto que acabamos de crear, modificaremos su propiedad DATE, por el valor agencyRecallDate de la entidad que recibe la función.
            archivoRecall.TIME = Convert.ToDateTime(resultsRecall.agencyRecallDate).ToString("hhmm"); //Lo mismo sucede con la propiedad time, la modificaremos para asignarle el valor de la propiedad agencyRecallDate pero tomando solo la hora y los minutos.
            archivoRecall.ACCOUNTNUMBER = resultsRecall.accountNumber.ToString().PadRight(20); //Tambien modificaremos la propiedad accountNumber, por el accountNumber d ela entidad que recibe la fución.
            //archivoRecall.RECOVERER_CODE = "";
            //archivoRecall.RECOVERER_ID = "";
            //archivoRecall.LOAN_CODE = "";

            List<spSelectProducto_Result> Resultado = new List<spSelectProducto_Result>(); //Creamos una lista de colecciones, para almacenar los resultados obtenidos por el SP spSelectProducto
            using (CYBEREntities DB = new CYBEREntities())
            {
                Resultado = DB.spSelectProducto(resultsRecall.accountNumber).ToList(); //Se ejecuta el SP spSelectProducto y se almacenan sus resultados en la lista creada anteriormente. El SP solo recibe el número de cuenta.
            }
            if (resultsRecall.agencyId != null) //si la entidad agencyId existe.
            {
                if (resultsRecall.agencyId.ToString().Length >= 4) //Y su valor es mayor a 4 caracteres de longitud.
                {
                    archivoRecall.RECOVERER_CODE = resultsRecall.agencyId.ToString().Trim().Substring(2, 4); //Solo se tomará del caracter 3 al 7.
                }
                else
                {
                    archivoRecall.RECOVERER_CODE = resultsRecall.agencyId.ToString().Trim().PadRight(4); //En caso de que no su longitud no sea mayor a 4 caracteres, se le añadiran espacios en blanco a la drecha para acompletar.
                }
            }
            //archivoRecall.RECOVERER_CODE = Resultado[0].TBAXATCURRENTAGENCYID.Substring(2, 4);
            if (Resultado.Count > 0)
            {
                archivoRecall.LOAN_CODE = Resultado[0].TBAXATPRODUCTCODE.ToString().PadRight(4).Substring(0, 4); //Se modifica la propiedad LOANCODE por el TBAXATPRODUCTCODE de la entidad AccountRecallInfoList que recibió la función.
            }
            else
            {
                MessageBox.Show("El número de cuenta: " + resultsRecall.accountNumber.ToString() + " NO posee un LOAN.CODE", "CUIDADO", MessageBoxButtons.OK);
                archivoRecall.LOAN_CODE = "NULL";
            }


            return archivoRecall; //Finalmente la función regresa el arbol de JSON archivoRecall
        }
        #endregion ArchivoRecall-

        /// <summary>
        /// Crea un JSON UPDATESIB con base a telefonos y RCS que se encuentren en un EXCEL que se carga.
        /// </summary>
        /// <returns></returns>
        public Task<DataTable> EjecutarAsynExcel()
        {
            return Task.Run(() =>
            {
                PRUEBA = new DataTable(); //Se crea un nuevo DataTable llamado PRUEBA   
                string pathes = Environment.GetFolderPath(Environment.SpecialFolder.Desktop);//Se obtiene la ruta del escritorio (Es una ruta especial)
                string archivo = pathes + "\\JSON\\UPDATESIB\\" + DateTime.Now.ToString("dd-MM-yyyy");//Y se le concatena una ruta para guardar una carpeta con la fecha de hoy, dentro de una carpeta llamad aUPDATESIb dentro de otra llamada JSON.
                if (!Directory.Exists(archivo)) //Sino existe ese directorio, lo creará.
                {
                    Directory.CreateDirectory(archivo);
                }
                IList<string> sec = new List<string>(); //Se crea una nueva Lista de tipo string llamada sec.
                using (CYBEREntities DB = new CYBEREntities())
                {
                    sec = DB.spSelectAmexSecuencia().ToList(); //Donde se almacenará lo obtenido por el SP spSelectAmexSecuencia, que es el ultimo secuencial de UPDATESIB que se tenga en la BD.
                }
                int sequencia = (Convert.ToInt32(sec[0]) + 1);/////Y se le suma 1 unidad al contador
                string fecha = DateTime.Now.ToString("MMddyy"); //Crea un string llamdo fecha, donde se almacenará la fecha de hoy. En formato MMddyy
                string NombreJson = "LZ.E2.ACORN.ST.UPDATES.V01." + fecha + "." + sequencia.ToString().PadLeft(4, '0') + ""; //Y se guarda en un string, el nombre que llevará el JSON que UPDATESIB-DEMOGRAPHICS EXCEL que se genere.
                string[] Dividido = NombreJson.Split('.'); //Se divide el nombre del JSON con un split por puntos. Y cada parte separada por un token, se almacenará en un elemento de un array llamado Dividido.
                int ContadorClases = 0; //Se crea un contador llamado ContadorClases inicializado en 0.
                Ent_Json_Update.RootObject UpdateJson = new Ent_Json_Update.RootObject();//Se crea un nuevo objeto raiz, de la clase Ent_Json_Update.
                string RutaCompleta = Path.GetDirectoryName(Txt_Archivo.Text) + "\\" + Path.GetFileName(Txt_Archivo.Text); //Se obtiene la dirección y finalmente el nombre del archivo que se haya seleccionado previamente.
