                string[] Dividido2 = NombreJson.Split('.');
                string rutaSave = archivo + "\\" + NombreJson; //Se concatena la ruta del escritorio, con la carpeta JSON, con la subcarpeta UPDATESIB, la carpeta con la fecha del dia de hoy, y finalmente el nuevo nombre que llevará el JSON. y se guarda en una variable rutaSave
                File.WriteAllText(rutaSave, output); //Y todo el texto del JSON que se encuentra  ahora en output, se almacena en este archivo en esta ruta. 
                GenerarHash(Dividido2, rutaSave);         //Se manda llamar el método GenerarHash para crear el archivo HASH.              
                MessageBox.Show("Archivo Generado", "COMPLETO", MessageBoxButtons.OK);
                return PRUEBA;
            });
        }

        /// <summary>
        /// Procesa un JSON para generar su archivo de asignación.
        /// Se pueden procesar 4 tipos de JSON.
        /// PLACEMENT, RECALL, UPDATESOB Y ACTIONHIST.
        /// </summary>
        /// <returns></returns>
        public Task<DataTable> EjecutarAsynJsonTotal()
        {
            return Task.Run(() =>
            {

                PRUEBA = new DataTable();
                while (true)
                {
                    DateTime horaInicio = DateTime.Now;
                    string Ruta = Environment.GetFolderPath(Environment.SpecialFolder.Desktop); //Obtiene la ruta especial del Escritorio para concatearla mas adelante.
                    string RutaCompleta = Path.GetDirectoryName(Txt_Archivo.Text) + "\\" + Path.GetFileName(Txt_Archivo.Text);//Obtiene el nombre del archivo que se acaba de cargar asi como la ruta de este.
                    string NombreJson = Path.GetFileName(RutaCompleta); //Almacena solamente el nombre del archivo.
                    string[] Dividido = NombreJson.Split('.'); //Y lo divide por puntos "." almacenandolo en un arreglo de cadenas.
