                        #region ACTIONHISTOB
                        case "ACTIONHISTOB": //En caso de que sea un ActionHistOB se realizará lo siguiente:
                            GenerarHash(Dividido, RutaCompleta); //Se genera el HASH primero que nada, enviando el arreglo Dividido, que contiene el nombre del JSOn separado por puntos. Y la Ruta completa donde se almacenará el archivo HASH,
                            resultsAction = new Ent_Json_Action.RootObject(); //Se crea un objeto que servirá como el árbol de la entidad Action del JSON. llamado resultsAction.
                            while (reader.Read()) //Mientras pueda leer algo, seguirá haciendolo 
                            {
                                resultsAction = serializer.Deserialize<Ent_Json_Action.RootObject>(reader); //y almacenando toda la estructura y datos en el árbol resultsAction.
                            }
                            fechasimple = DateTime.Now.ToString("dd-MM-yyyy");
                            fechahora = DateTime.Now.ToString("dd-MM-yyyy HHmmss");
                            archivo = Ruta + "\\JSON\\ACTION\\" + fechasimple;//Se modifica la cadena archivo, con la ruta donde se almacenara el archivo mas la subcarpeta JSON, la sub sub carpeta ACTION y una carpeta individual con la fecha del dia de procsamiento.
                            archivoC = "C:";
                            var max_Query = 0; //Se crea una variable max_Query inicializada en 0. que será de tipo entero de 32 bits con signo. Para almacenar el ID maximo de la tabla Tab_Amex_ActionsHistory
                            using (CYBEREntities DB = new CYBEREntities()) //Se crea una conexión a la base de datos.
                            {
                                DB.Database.CommandTimeout = 600; //Se establece el timeout a 600.
                                max_Query = (from tab1 in DB.Tab_Amex_ActionsHistory //Y se obtiene el id Máximo que exista en la tabla Tab_Amex_ActionsHistory. Y su resultado se almacena en tab_amex_actionsHiso
                                             select tab1.TBAXATID).Max();
                            }

                            Ent_Guardar_Json GuardarAction = new Ent_Guardar_Json(); //Se crea un objeto de la clase Etn_Guardar_Json que nos servirá para almacenar en la BD la informacion del JSON.
                            GuardarAction.Actions(resultsAction); //Y utilizando el objeto previamente creado. Almacenaremos todas las partes del JSON ACTIONHISTOB.
                            IList<spSelectAmexUpdateNOTE_Result> NOTAS = new List<spSelectAmexUpdateNOTE_Result>(); //Se crea una nueva lista llamada NOTAS. La cual será de tipo spSelectAmexUpdateNOTE_Result
                                                                                                                    //Y nos permitirá almacenar los resultados del STORED PROCEDURE spSelectAmexUpdateNOTE
                            using (CYBEREntities DB = new CYBEREntities())
                            {
                                DB.Database.CommandTimeout = 600; //Este SP no toma de la Tab_Amex_Update, sino de la Tab_Amex_ActionsHistory
                                NOTAS = DB.spSelectAmexUpdateNOTE(max_Query).ToList(); //Este SP primero cambiara todos los caracteres que pudieran afectar el proceso de asignación. Como reemplazar 
                                                                                       //á por a, é por e, ñ por una n... etc...etc.. En todos los registros donde el id sea mayor al valor de la variable max_Query. Por lo que esto solo afectará a los registros que se acaban 
                                                                                       //de insertar en la Tabla. Y finalmente nos trae ordenados los números de cuenta y updatedate 
                            }
                            DataTable NOTASFINAL = new DataTable(); //Creamos un DataTable llamado NOTSFINAL.
                            NOTASFINAL.Columns.Add("CUENTA"); //Al cual le añadiremos todas las columnas siguientes.
                            NOTASFINAL.Columns.Add("CONSECUTIVO");
                            NOTASFINAL.Columns.Add("FECHA1");
                            NOTASFINAL.Columns.Add("NOTA1");
                            NOTASFINAL.Columns.Add("FECHA2");
                            NOTASFINAL.Columns.Add("NOTA2");
                            NOTASFINAL.Columns.Add("FECHA3");
                            NOTASFINAL.Columns.Add("NOTA3");
                            NOTASFINAL.Columns.Add("FECHA4");
                            NOTASFINAL.Columns.Add("NOTA4");
                            NOTASFINAL.Columns.Add("FECHA5");
                            NOTASFINAL.Columns.Add("NOTA5");
                            NOTASFINAL.Columns.Add("FECHA6");
                            NOTASFINAL.Columns.Add("NOTA6");
                            NOTASFINAL.Columns.Add("FECHA7");
                            NOTASFINAL.Columns.Add("NOTA7");
                            NOTASFINAL.Columns.Add("FECHA8");
                            NOTASFINAL.Columns.Add("NOTA8");
                            NOTASFINAL.Columns.Add("FECHA9");
                            NOTASFINAL.Columns.Add("NOTA9");
                            NOTASFINAL.Columns.Add("FECHA10");
                            NOTASFINAL.Columns.Add("NOTA10");
                            NOTASFINAL.Columns.Add("FECHA11");
                            NOTASFINAL.Columns.Add("NOTA11");
                            NOTASFINAL.Columns.Add("FECHA12");
                            NOTASFINAL.Columns.Add("NOTA12");
                            NOTASFINAL.Columns.Add("FECHA13");
                            NOTASFINAL.Columns.Add("NOTA13");
                            NOTASFINAL.Columns.Add("VACIO");
                            ///////
                            for (int i = 0; i < NOTAS.Count; i++) //Ahora crearemos un ciclo for, que recorrera todo el tamaño de la lista NOTAS. Que recordemos se llenó con el SP anterior.
                            {
                                StringBuilder Valor = new StringBuilder(); //Creamos tambien un nuevo objeto de la clase StringBuilder llamado Valor.
                                string Cuenta = NOTAS[i].TBAXATACCOUNTNUMBER; //Creamos una cadena llamada Cuenta, que almacenará el valor del número de cuenta del objeto de la lista NOTAS con indice i.
                                if (i + 1 < NOTAS.Count)//Aqui comprobamos que no se vaya desbordar la memoria si intentamos acceder a un indice más.
                                {
                                    List<DateTime?> FECHAS = new List<DateTime?>();//Creamos una nueva lista llamda FECHAS, que será una lista de tipo DateTime.
                                    string Cuenta2 = NOTAS[i + 1].TBAXATACCOUNTNUMBER;  //Y revisamos si la siguiente cuenta en ser revisada, posee el mismo número de cuenta.
                                    while (Cuenta == Cuenta2) //En caso de que si...y mientras tanto.
                                    {
                                        /////////////////////////////////////////***************************************************
                                        for (int a = 0; a < Convert.ToDouble(NOTAS[i].TBAXATNOTE.Length) / Convert.ToDouble(40); a++) //Siempre que la longitud del campo TBAXATNOTE sea mayor a 40 caracteres
                                                                                                                                      //Se añadirá la misma updateDate a la lista FECHAS. Esto será por que el comentario se dividirá en arreglos de 40 caracteres como máximo y la fecha del siguiente registro debe ser la misma
                                                                                                                                      //En otras palabras, el tamaño máximo de token es de 40 caracteres. Después de eso, se corta la linea de texto, se añade la fecha nuevamente, y son otros 40 caracteres de texto, y asi sucesivamente.
                                        {
                                            FECHAS.Add(NOTAS[i].TBAXATUPDATEDATE);//Se añade la fecha a la lista.
                                        }
                                        Valor.Append(NOTAS[i].TBAXATNOTE + ""); //Y se concatena al StringBuilder Valor, el campo TBAXATNOTE y un caracter nulo. Se concatenan todos los campos TBAXATNOTE para una misma cuenta
                                                                                //Ahora Valor, contiene TODO el TBAXATNOTE. Por más caracteres que sean.
                                        i++; //Se incrementa el contador de la lista NOTAS.
                                        if (i + 1 < NOTAS.Count) //Y se modifica la cadena Cuenta2 en caso de que aun haya cadenas restantes por revisar.
                                        {
                                            Cuenta2 = NOTAS[i + 1].TBAXATACCOUNTNUMBER; //se toma el valor de la cadena siguiente.
                                            if (Cuenta != Cuenta2)
                                            {
                                                for (int a = 0; a < Convert.ToDouble(NOTAS[i].TBAXATNOTE.Length) / Convert.ToDouble(40); a++)
                                                {
                                                    FECHAS.Add(NOTAS[i].TBAXATUPDATEDATE);//Se añade la fecha a la lista.
                                                }
                                                Valor.Append(NOTAS[i].TBAXATNOTE + ""); //Para no perder ningun comentario, se concatena el ultimo indice nuevo, en caso de que el siguiente no sea igual en el numero de cuenta.
                                            }
                                        }
                                        else
                                            break;
                                    }
                                    //double Division = Convert.ToDouble(Valor.Length) / Convert.ToDouble(480); //Ahora se divide la longitud de la cadena concatenada y se divide entre 480 para obtener el valor de Division.
                                    //La linea anterior, no se utiliza.
                                    DataRow Nuevo = NOTASFINAL.NewRow(); //Se crea un nuevo DataRow llamado Nuevo; Para añadir un nuevo conjunto de datoos a nuestro dataTable NOTASFNAL.
                                    int contador = 1, ContadorH = 0, ContadorF = 0; //Se crean 3 contadores nuevos.
                                                                                    //Contador, comienza en 1, y nos permite llevar la cuenta de los ciclos realizados, para que sean 13 en total. Que son el numero total de ciclos que cabe en una misma linea del ACTIONHIST.
                                                                                    //ContadorH, nos permite llevar la cuenta del numero total de lineas de una misma cuenta en el ACTIONHIST. En otras palabras, el total de saltos de linea para una misma cuenta.
                                                                                    //El contadorF, nos permite 
                                    while (contador < 15) //Mientras el contador sea menor a 15 - (SE REALIZAN 14 CICLOS.)
                                    {
                                        if (contador == 14)//Cuando el contador este en su penultimo ciclo.
                                        {
                                            Nuevo["CUENTA"] = NOTAS[i].TBAXATACCOUNTNUMBER.PadRight(20);//En la columna CUENTA de nuestro DataRow Nuevo, colocaremos el numero de cuenta a 20 caracteres.
                                            Nuevo["CONSECUTIVO"] = "H" + ContadorH.ToString().PadLeft(2, '0'); //Se crea el Consecutivo que puede ir desde 00 a 99, concatenado con una H
                                            Nuevo["VACIO"] = "B".PadLeft(53);//Y se crea la parte final con 52 espacios en blanco y una B al final.
                                            contador = 1; //Se reinicia el contador de columnas.
                                            ContadorH++;//Se incrementa en 1 el contador Historico.
                                            NOTASFINAL.Rows.Add(Nuevo);//Y se añade el DataRow que acabamos de crear al DataTable NOTASIFINAL.
                                            Nuevo = NOTASFINAL.NewRow(); //Se reinicia el DataRow para volver a ingresar los datos de manera ordenada.
                                            if (Valor.Length < 40) //Si ya no hay más datos que procesar en el string Valor, se cierra el ciclo y se continua con las demas cuentas.
                                            {
                                                break;
                                            }
                                        }//Sino es su penultimo ciclo.
                                        else //Los otros 13 ciclos.
                                        {
                                            if (Valor.Length > 40) //Si la longitud del StringBuilder es mayor a 40. La información debe ser recortada en 40 caracteres y asignada a una columna de comentario/NOTA
                                            {
                                                Nuevo["FECHA" + contador.ToString()] = Convert.ToDateTime(FECHAS[ContadorF]).ToString("yyyyMMdd"); //Se asigna la fecha de la lista FECHAS en el indice Contador F. A la columna FECHA1,2,3..o cual sea el valor del contador. Al DataRow.
                                                Nuevo["NOTA" + contador.ToString()] = Valor.ToString().Substring(0, 40); //Y se realiza lo mismo con los primeros 40 caracteres para la columna NOTA1,2,3,etc....
                                                Valor.Remove(0, 40); //Y posteriormente removemos los primeros 40 caracteres para reducir el tamaño de la cadena Valor.
                                            }
                                            else //Si al longitud ya no supera los 40 caracteres hay 2 opciones...
                                            {
                                                if (Valor.Length > 0)//Si es menor a 40, pero mayor a 0.                                                                
                                                {
                                                    Nuevo["FECHA" + contador.ToString()] = Convert.ToDateTime(FECHAS[ContadorF]).ToString("yyyyMMdd");  //Se asigna la fecha ultimo indice de la lista FECHAS para una misma cuenta.
                                                    Nuevo["NOTA" + contador.ToString()] = Valor.ToString().Substring(0).PadRight(40);//Y se obtienen los ultimos caracteres para llenar esa columna, haciendole un PadRight para rellenar un total de 40 caracteres.
                                                    Valor.Remove(0, Valor.Length);//Y se remueven los últimos caracteres para dejar la cadena vacia.
                                                }
                                                else //Si la cadena ya esta vacia.
                                                {
                                                    Nuevo["FECHA" + contador.ToString()] = DateTime.Now.ToString("yyyyMMdd");//Se añadirá la fecha de hoy para rellenar las últimas columnas.
                                                    Nuevo["NOTA" + contador.ToString()] = " ".PadLeft(40);//Y la nota serán 40 espacios en blanco para las columnas restantes.
                                                }
                                            }
                                            contador++;//Se incrementa el contador de columnas Fecha y NOTA
                                            ContadorF++;//Se incrementa el contador del indice de las lista FECHAS.
                                        }
                                    }
                                }
                            }
                            NOTAS.Clear(); //Se borra de la memoria el contenido de la lista NOTAS.
                            NOTAS = null; //Y se le asigna un valor nulo.
