        /// <summary>
        /// Almacena en la Tabla de SQLServer lo obtenido durante la generación del JSON UPDATESIB de la BD de Oracle.
        /// </summary>
        /// <param name="Total"></param>
        /// <param name="Fecha"></param>
        /// <returns></returns>
        public static string QuerySQL(DataTable Total, DateTime Fecha) //Inicia el método QuerySQL, recibe un Datatble y una Fecha.
        {
            string connectionString = "data source = 192.168.50.51; database = CYBER; User = usuarioCBY; password = C1bercyb; Connect Timeout = 90000";
            //Se crea una cadena connectionString, con los datos necesarios para realizar la conexión a la base Cyber.
            string mensaje; //Se declara  una cadena mensaje, sin ningun valor.
            using (SqlConnection objSqlConnection = new SqlConnection(connectionString)) //Se crea un objeto de conexión, utilizando connectionString, que se declaró anteriormente.
            {
                try //Se crea un try-catch
                {
                    #region Instancia de los parametros
                    SqlParameter sqlP_1 = new SqlParameter(); //Se crean 2 parametros SQL. sqlP_1 y sqlP_2
                    SqlParameter sqlP_2 = new SqlParameter();

                    #endregion


                    #region Nombre de los parametros
                    sqlP_1.ParameterName = "@i_tPaso"; //Se les asigna nombre a ambos parametros.
                    sqlP_2.ParameterName = "@i_dFecha";



                    #endregion

                    #region Tipo de variable de los parametros
                    sqlP_1.SqlDbType = SqlDbType.Structured; //Se les asigna un tipo de dato.
                    sqlP_2.SqlDbType = SqlDbType.Date;



                    #endregion

                    #region Tamaño del parametro 
                    //Se les asigna tamaño (?)



                    #endregion

                    #region Dirección del parametro
                    //Se les asigna direccion (?)

                    #endregion

                    #region Asignacion de los valores
                    sqlP_1.Value = Total;
                    sqlP_2.Value = Fecha;
                    // Se les asigna un valor, con los parametros recibidos por el método QuerySQL


                    #endregion

                    #region Creación de arreglo de parametros
                    SqlParameter[] mySQLParametros = new SqlParameter[] //Se crea un arreglo de Parametros SQL, con 2 parametros. sqlP_1 y sqlP_2
                    {   sqlP_1,sqlP_2
                    };
                    #endregion

                    //Abrir conexion
                    objSqlConnection.Open(); //Se abre la conexión con la base de datos, usando objqSqlConnection, que utiliza connectionString

                    //Ejecutar sentencia
                    using (SqlCommand objSqlCommand = new SqlCommand("spInsertTabAmexUpdate", objSqlConnection))
                    /*
                     * ALTER PROCEDURE [dbo].[spInsertTabAmexUpdate]
                     *  @i_tPaso Tab_Amex_Update READONLY,
                     *  @i_dFecha DATE 
                     *  AS   
                     *  SET NOCOUNT ON  	
                     *  DELETE Tab_Amex_Update where FECHA >= @i_dFecha;
                     *  INSERT INTO Tab_Amex_Update	  
                     *  SELECT * FROM  @i_tPaso
                     * */
                    //Se crea un Comando SQL. Utilizando la conexión objSqlConnection, y el Stored Procedure spInsertTabAmexUpdate.
                    {
                        //var returnParameter; Representa un parámetro de un objeto SqlCommand.
                        // 
                        var returnParameter = objSqlCommand.Parameters.Add("@ReturnVal", SqlDbType.Int); //Añade el parametro llamado "ReturnVal", que será
                        //de tipo Int.  
                        returnParameter.Direction = ParameterDirection.ReturnValue; //Asigna ReturnValue al atributo Direction de nuestro objeto returnParameter.
                        mensaje = string.Empty; //Se crea una cadena mensaje, que estará vacia.
                        objSqlCommand.CommandType = CommandType.StoredProcedure; //objSqlCommand será un comando de tipo StoredProcedure. Se le asigna este tipo a CommandType.
                        objSqlCommand.Parameters.AddRange(mySQLParametros); //Y sus parametros serán sqlP_1 y sqlP_2, que son respectivamente el DataTable y la Fecha que se
                        //recibieron al inicio del método.
                        objSqlCommand.ExecuteScalar(); //Se ejecuta el StoredProcedure, y devuelve la primer columna de la primera fila del conjunto de resultados devuelto por la consulta.
                        mensaje = returnParameter.Value.ToString(); //Lo obtenido por el comando lo guarda como la cadena mensaje.
                    }
                    //Cerrar conexion
                    objSqlConnection.Close();//Se cierra la conexión
                }
                catch (Exception exc) //Se realiza un catch a cualquier excepción que pudiera.
                {
                    objSqlConnection.Close();//Si hay alguna excepción lo primero será cerrar la conexión,
                    mensaje = string.Empty; //Se crea un string llamado mensaje. Estará vacio.
                    mensaje = exc.Message.ToString(); //Se guardará la excepción en el String mensaje.
                }
            }
            return mensaje; //Se regresará un string, vacio si funcionó todo bien. O con la excepción que se haya atrapado.
            //Finaliza Descarga SQL - 05
        }

        /// <summary>
        /// Genera un Excel en la Ruta que recibe como parametro, con los saldos obtenidos por el SP
        /// spSelectAmexUpdateSALDOS. Con las columnas:
        /// Cyclecut, AccountNumber, Currentamountdue, 30, 60, 90, 120, 150, 180.
        /// </summary>
        /// <param name="archivo"></param>
        /// <returns></returns>
                public DataTable GenerarSaldos(string archivo) 
                {
                    DataTable Tabla = new DataTable(); //Se crea un nuevo DataTable llamado Tabla
                IList<spSelectAmexUpdateSALDOS_Result> result = new List<spSelectAmexUpdateSALDOS_Result>(); //Una nueva lista llamada result que contendra
                    //Los resultados obtenidos por ejecutar el SP spSelectAmexUpdateSALDOS
                    using (CYBEREntities DB = new CYBEREntities()) //Se realiza la conexión usando CYBEREntities 
                    {
                        result = DB.spSelectAmexUpdateSALDOS().ToList(); //Y el resultado del SP se almacena en la lista result. //No obtiene de Tab_amex_Update sino de [Tab_Amex_CustomerFinancial]
                    }
                    if (result.Count > 0) //Si el SP trajo registros, se crean las siguientes columnas en la DataTable.
                    {
                        Tabla.Columns.Add("Cyclecut");
                        Tabla.Columns.Add("Accountnumber");
                        Tabla.Columns.Add("Currentamountdue");
                        Tabla.Columns.Add("30");
                        Tabla.Columns.Add("60");
                        Tabla.Columns.Add("90");
                        Tabla.Columns.Add("120");
                        Tabla.Columns.Add("150");
                        Tabla.Columns.Add("180");
                        for (int i = 0; i < result.Count; i++) //Después por cada uno de los registros que haya regresado el SP. Se iran llenando las filas.
                        {
                            Tabla.Rows.Add(result[i].CYCLECUT, result[i].ACCOUNTNUMBER, result[i].CURRENTAMOUNTDUE, result[i].TBAXCLAMOUNTDUE30DAYS, result[i].TBAXCLAMOUNTDUE60DAYS, result[i].TBAXCLAMOUNTDUE90DAYS, result[i].TBAXCLAMOUNTDUE120DAYS, result[i].TBAXCLAMOUNTDUE150DAYS, result[i].TBAXCLAMOUNTDUE180DAYS);
                        }
                        Ent_Excel Excel = new Ent_Excel(); //se crea una Entidad Excel para poder pasar estos datos a un excel.
                        Excel.ConvertToExcel(Tabla, archivo);//Se llena una hoja de Excel, con los datos obtenidos en el DataTable, en la ruta "archivo"
                    }
                    return Tabla;
                }

