                #region CreacionEspacios- TreatmentList
                if (result.Count > 0) //Si la lista result contiene al menos 1 elemento.
                {

                    for (int i = 0; i < result.Count; i++)
                    {
                        DateTime? offerResult = null, acceptResult = null, expirationResult = null;
                        if (result[i].D5 == "AH" || result[i].D5 == "RV")
                        {
                            // if (result[i].D6 == "YA" || result[i].D6 == "RI" || result[i].D6 == "YS" || result[i].D6 == "NS" || result[i].D6 == "AI" || result[i].D6 == "OY" || result[i].D6 == "OO" || result[i].D6 == "NI" || result[i].D6 == "NA")
                            if (result[i].D6 == "YA" || result[i].D6 == "RI" || result[i].D6 == "YS" || result[i].D6 == "AI" || result[i].D6 == "OY" || result[i].D6 == "PA")
                            {
