                                    string[] ArrayD9 = result[i].D9.ToString().Trim().Split(';');
                                    if (ArrayD9.Length == 3) //Comprobamos que el arreglo tenga 3 elementos --> FECHA;MONTO;412 0 1 2
                                    {
                                        if (ArrayD9[2].ToString().Trim().Substring(0, 1) == "4" && ArrayD9[2].ToString().Trim().Substring(2, 1) == "2" && ArrayD9[2].ToString().Trim().Length == 3)
                                        {
                                            if (!result[i].D9.ToString().Trim().Contains("CONVENIOS"))
