                                                    UpdateJson.treatmentList.Add(new TreatmentList());
                                                }
                                                ContadorClases++;
                                            }
                                        }
                                    }
                                    else
                                    {
                                        if (ArrayD9.Length == 4) //Comprobamos que el arreglo tenga 4 elementos --> FECHA;MONTO;FECHA;FECHA 0 1 2 3
                                        {
                                            if (!result[i].D9.ToString().Trim().Contains("CONVENIOS"))
                                            {
                                                string[] SaldoArrayResult = ArrayD9[1].ToString().Split('.'); //Le hace un split al SALDO!!!!! al SALDO SOLAMENTEEEEE
                                                if (!(SaldoArrayResult.Length > 2))
                                                {
                                                    ////Versión R9.7. 27/02/2020 Se modifica tratamiento de Settlement Etapa 2; con base al REQ - 2020-022544 por Miriam Trujano.
                                                    if (ArrayD9[3].Split('.').Length > 1) //Aqui se comprueba que No sea una reasignación, es decir que D9 no sea tipo dd/MM/yyyy.R
                                                    {
                                                        if (UpdateJson.treatmentList == null)
                                                        {
                                                            UpdateJson.treatmentList = new List<TreatmentList>();
                                                            UpdateJson.treatmentList.Add(new TreatmentList());
                                                        }
                                                        else
                                                        {
                                                            UpdateJson.treatmentList.Add(new TreatmentList());
                                                        }
                                                        ContadorClases++;
                                                    }
                                                    else
                                                    {
                                                        offerResult = Convert.ToDateTime(ArrayD9[3]);
                                                        acceptResult = Convert.ToDateTime(ArrayD9[0]);
                                                        expirationResult = Convert.ToDateTime(ArrayD9[2]);
                                                        if (offerResult <= acceptResult && acceptResult <= expirationResult)
                                                        {
                                                            if (UpdateJson.treatmentList == null)
                                                            {
                                                                UpdateJson.treatmentList = new List<TreatmentList>();
                                                                UpdateJson.treatmentList.Add(new TreatmentList());
                                                            }
                                                            else
                                                            {
                                                                UpdateJson.treatmentList.Add(new TreatmentList());
                                                            }
