                                    if (CurrentAmountDue == null || AmountDue30Days == null || AmountDue60Days == null || AmountDue90Days == null || AmountDue120Days == null || AmountDue150Days == null || AmountDue180Days == null)
                                    {
                                        List<spSelectSertecCamposFCS_Result> Resultado = new List<spSelectSertecCamposFCS_Result>();
                                        using (CYBEREntities DB = new CYBEREntities())
                                        {
                                            Resultado = DB.spSelectSertecCamposFCS(accountNumber).ToList();
                                        }
                                        if (Resultado.Count != 0)
                                        {
                                            if (CurrentAmountDue == null) { CurrentAmountDue = Convert.ToDouble(Resultado[0].TBAXCLCURRENTAMOUNTDUE); }
                                            if (AmountDue30Days == null) { AmountDue30Days = Convert.ToDouble(Resultado[0].TBAXCLAMOUNTDUE30DAYS); }
                                            if (AmountDue60Days == null) { AmountDue60Days = Convert.ToDouble(Resultado[0].TBAXCLAMOUNTDUE60DAYS); }
                                            if (AmountDue90Days == null) { AmountDue90Days = Convert.ToDouble(Resultado[0].TBAXCLAMOUNTDUE90DAYS); }
                                            if (AmountDue120Days == null) { AmountDue120Days = Convert.ToDouble(Resultado[0].TBAXCLAMOUNTDUE120DAYS); }
                                            if (AmountDue150Days == null) { AmountDue150Days = Convert.ToDouble(Resultado[0].TBAXCLAMOUNTDUE150DAYS); }
                                            if (AmountDue180Days == null) { AmountDue180Days = Convert.ToDouble(Resultado[0].TBAXCLAMOUNTDUE180DAYS); }

                                        }
                                        else
                                        {
                                            //MessageBox.Show("ALERTA! PARA LA CUENTA: " + accountNumber + " NO EXISTE UN REGISTRO CURRENT-180", "CUIDADO", MessageBoxButtons.OK);
                                        }
                                    }
                                    if (!(AmountDue180Days != 0 && AmountDue180Days != null))
                                    {
                                        if (!(AmountDue150Days != 0 && AmountDue150Days != null))
                                        {
                                            if (!(AmountDue120Days != 0 && AmountDue120Days != null))
                                            {
                                                if (!(AmountDue90Days != 0 && AmountDue90Days != null))
                                                {
                                                    if (!(AmountDue60Days != 0 && AmountDue60Days != null))
                                                    {
                                                        if (!(AmountDue30Days != 0 && AmountDue30Days != null))
                                                        {
                                                            if (!(CurrentAmountDue != 0 && CurrentAmountDue != null))
                                                            {
                                                                OldestAgeMinBucket = 0;
                                                            }
                                                            else
                                                                OldestAgeMinBucket = CurrentAmountDue;
                                                        }
                                                        else
                                                            OldestAgeMinBucket = AmountDue30Days;
                                                    }
                                                    else
                                                        OldestAgeMinBucket = AmountDue60Days;
                                                }
                                                else
                                                    OldestAgeMinBucket = AmountDue90Days;
                                            }
                                            else
                                                OldestAgeMinBucket = AmountDue120Days;
                                        }
                                        else
                                            OldestAgeMinBucket = AmountDue150Days;
                                    }
                                    else
                                        OldestAgeMinBucket = AmountDue180Days;
                                    if (CurrentAmountDue == null && AmountDue30Days == null && AmountDue60Days == null && AmountDue90Days == null && AmountDue120Days == null && AmountDue150Days == null && AmountDue180Days == null)
                                    {

                                    }
                                    else
                                    {
                                        object[] o = { ciclo, accountNumber, CurrentAmountDue, AmountDue30Days, AmountDue60Days, AmountDue90Days, AmountDue120Days, AmountDue150Days, AmountDue180Days, "-", OldestAgeMinBucket, agencia, "-" };
                                        FCS.Rows.Add(o);
                                    }
                                }
                                break;
                            }//fin del while
                        }
                        Ent_Excel Excel = new Ent_Excel(); //se crea una Entidad Excel para poder pasar estos datos a un excel.
                        Excel.ConvertToExcelFCS(FCS, RutaCompleta, SeqNo);//Se llena una hoja de Excel, con los datos obtenidos en el DataTable, en la ruta "archivo"
                        using (CYBEREntities DB = new CYBEREntities())
                        {
                            DB.spInsertSecuencialAmexJSON(NombreJson, Convert.ToString(SeqNo).PadLeft(4, '0'), "FCS", loginGlobal, FCS.Rows.Count.ToString(), horaInicioFCS, DateTime.Now);
                        }
                        MessageBox.Show("EL ARCHIVO SE GENERÓ EN \\Desktop\\FCS\\DIA", "FCS GENERADO", MessageBoxButtons.OK);
                        break;
                    }
                }
            }
        }
        #endregion
        #endregion METODOS
